    // ─────────── فصل ۱: ایتاکا و تلماکوس ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Ithaca and Telemachus", titlePersian = "ایتاکا و تلماکوس",
        paragraphs = listOf(
            StoryParagraph("Sing to me, Muse, of the man of many ways, who wandered long after he had sacked the sacred city of Troy.", "ای موز، برایم بخوان از مردِ بسیار‌راه‌رفته، که پس از غارت شهر مقدس تروا، سال‌ها سرگردان شد."),
            StoryParagraph("Many were the men whose cities he saw and whose minds he learned, and many the sorrows he suffered in his heart upon the sea.", "بسیار بودند مردمانی که شهرهایشان را دید و ذهن‌هایشان را شناخت و بسیار بودند رنج‌هایی که در دلش بر دریا کشید."),
            StoryParagraph("He strove to save his life and to bring his comrades home to their native land.", "تلاش کرد جان خود را نجات دهد و یارانش را به سرزمین مادری‌شان بازگرداند."),
            StoryParagraph("But he could not save them, though he longed to; for they perished by their own blind folly.", "اما نتوانست نجاتشان دهد، هرچند سخت می‌خواست؛ زیرا آنان به سبب حماقت کورکورانه خودشان هلاک شدند."),
            StoryParagraph("Fools, who devoured the cattle of Helios the Sun, and he took from them the day of their return.", "احمق‌ها، که گاوهای هلیوس خورشید را خوردند و او روز بازگشتشان را از آنان گرفت."),
            StoryParagraph("Tell me also of these things, O goddess, daughter of Zeus, beginning wherever you will.", "این چیزها را نیز برایم بگو، ای الهه، دختر زئوس، از هر جا که می‌خواهی آغاز کن."),
            StoryParagraph("Now all the others who had escaped death were at home, safe from the perils of war and sea.", "اکنون همه دیگرانی که از مرگ گریخته بودند در خانه بودند، ایمن از خطرات جنگ و دریا."),
            StoryParagraph("But Odysseus alone, who longed for his home and his wife, was held captive by the nymph Calypso.", "اما تنها اودیسئوس، که مشتاق خانه و همسرش بود، اسیر پری دریایی کالیپسو بود."),
            StoryParagraph("She kept him in her hollow caves, longing to have him for her husband.", "او را در غارهای توخالی‌اش نگه می‌داشت و مشتاق بود او را شوهر خود کند."),
            StoryParagraph("But when the years came round, the year in which the gods had spun that he should return to Ithaca, he was not yet free from trials.", "اما چون سال‌ها گذشت، سالی که خدایان مقدر کرده بودند به ایتاکا بازگردد، هنوز از آزمون‌ها رها نبود."),
            StoryParagraph("Even his own people he had not yet reached; but the gods pitied him, all except Poseidon.", "حتی به مردم خودش هم نرسیده بود؛ اما خدایان بر او رحم آوردند، همه جز پوزئیدون."),
            StoryParagraph("Poseidon was fiercely angry with the godlike Odysseus until he reached his own land.", "پوزئیدون به‌شدت بر اودیسئوس خداشکل خشمگین بود تا آنکه به سرزمین خودش رسید."),
            StoryParagraph("But now Poseidon had gone to the far-off Ethiopians, and the other gods met in the house of Olympian Zeus.", "اما اکنون پوزئیدون به سرزمین دور اتیوپیایی‌ها رفته بود و دیگر خدایان در خانه زئوس المپی گرد آمده بودند."),
            StoryParagraph("And the father of gods and men was the first to speak, for he was thinking of Aegisthus in his heart.", "و پدر خدایان و مردمان نخستین کسی بود که سخن گفت، زیرا در دلش به آگیستوس می‌اندیشید."),
            StoryParagraph("'How strangely men blame the gods!' he said. 'They say their troubles come from us.'", "گفت: «چقدر عجیب مردمان خدایان را سرزنش می‌کنند! می‌گویند گرفتاری‌هایشان از ماست.»"),
            StoryParagraph("'But it is by their own folly that they bring suffering upon themselves beyond what is fated.'", "«اما به سبب حماقت خودشان است که رنجی فراتر از تقدیر بر خود می‌آورند.»"),
            StoryParagraph("'So it was with Aegisthus, who took the wife of Agamemnon, and killed him on his return, though he knew it meant destruction.'", "«چنین بود با آگیستوس، که زن آگاممنون را گرفت و او را به هنگام بازگشتش کشت، هرچند می‌دانست این به معنای نابودی است.»"),
            StoryParagraph("'We warned him, sending Hermes to tell him not to do it, but he did not heed.'", "«هشدارش دادیم و هرمس را فرستادیم تا بگوید چنین نکن، اما گوش نکرد.»"),
            StoryParagraph("'And so he has paid the price in blood, as he deserved.'", "«و اینگونه بهایش را با خون پرداخت، همانطور که سزاوار بود.»"),
            StoryParagraph("Then Athena, the bright-eyed goddess, answered him.", "آنگاه آتنا، الهه روشن‌چشم، پاسخش داد."),
            StoryParagraph("'Father Zeus, that man lies dead, and rightly so,' she said.", "گفت: «پدر زئوس، آن مرد مرده است و درست هم مرده است.»"),
            StoryParagraph("'But my heart is torn for Odysseus, the wise and unlucky, who suffers so long from his longing for home.'", "«اما دلم برای اودیسئوس، فرزانه و بداقبال، پاره‌پاره است، که این همه سال از شوق خانه رنج می‌کشد.»"),
            StoryParagraph("'He is held on an island in the sea, where the navel of the sea is, a wooded island.'", "«او در جزیره‌ای در دریا نگه داشته شده، همان‌جا که ناف دریاست، جزیره‌ای جنگلی.»"),
            StoryParagraph("'And there dwells a goddess, the daughter of Atlas, who knows the depths of the sea.'", "«و آنجا الهه‌ای خانه دارد، دختر اطلس، که اعماق دریا را می‌شناسد.»"),
            StoryParagraph("'She keeps the unhappy man, and ever with soft and flattering words she charms him to forget Ithaca.'", "«او آن مرد بدبخت را نگه می‌دارد و پیوسته با سخنان نرم و فریبنده افسونش می‌کند تا ایتاکا را فراموش کند.»"),
            StoryParagraph("'But Odysseus, longing even to see the smoke rising from his own land, longs to die.'", "«اما اودیسئوس، که حتی آرزوی دیدن دود برخاسته از سرزمین خودش را دارد، آرزوی مرگ می‌کند.»"),
            StoryParagraph("'And yet, O Olympian, your heart does not soften. Do the gods not honor him for his sacrifices in Troy?'", "«و با این حال، ای المپی، دلت نرم نمی‌شود. آیا خدایان او را برای قربانی‌هایش در تروا حرمت نمی‌نهند؟»"),
            StoryParagraph("'Why then, Zeus, are you so angry with him?'", "«پس چرا، زئوس، این‌گونه بر او خشمگین هستی؟»"),
            StoryParagraph("Then Zeus, the cloud-gatherer, answered her and said:", "آنگاه زئوس، ابرگردآور، پاسخش داد و گفت:"),
            StoryParagraph("'My child, what strange words have escaped the barrier of your teeth?'", "«فرزندم، چه سخنان عجیبی از حصار دندان‌هایت گذشت؟»"),
            StoryParagraph("'How could I forget the godlike Odysseus, who is beyond all men in wisdom, and beyond all in the offerings he has made?'", "«چگونه می‌توانم اودیسئوس خداشکل را فراموش کنم، که در فرزانگی از همه مردمان پیش است و در پیشکش‌هایی که کرده از همه پیش‌تر؟»"),
            StoryParagraph("'No, it is Poseidon, the earth-shaker, who is angry with him, because he blinded his dear son, Polyphemus.'", "«نه، این پوزئیدون است، زمین‌جنبان، که بر او خشمگین است، زیرا پسر عزیزش، پولیفموس را کور کرد.»"),
            StoryParagraph("'For that, Poseidon does not kill him, but drives him wandering far from his native land.'", "«به همین سبب، پوزئیدون او را نمی‌کشد، اما او را از سرزمین مادری‌اش دور می‌گرداند.»"),
            StoryParagraph("'But come now, let us all plan his return. Poseidon must give up his anger, for he cannot stand alone against all the gods.'", "«اما اکنون بیایید، همگی برای بازگشتش نقشه بکشیم. پوزئیدون باید خشمش را رها کند، زیرا نمی‌تواند تنها در برابر همه خدایان بایستد.»"),
            StoryParagraph("Then Athena said: 'Father, if it is now the pleasure of the blessed gods that Odysseus return to his home, then let us send Hermes to Calypso.'", "آنگاه آتنا گفت: «پدر، اگر اکنون خواست خدایان سعادتمند است که اودیسئوس به خانه‌اش بازگردد، پس هرمس را نزد کالیپسو بفرستیم.»"),
            StoryParagraph("'Let him tell her our unshakable will, that Odysseus shall return to his own land.'", "«بگو به او اراده تزلزل‌ناپذیر ما را برساند، که اودیسئوس به سرزمین خودش بازخواهد گشت.»"),
            StoryParagraph("'And I will go to Ithaca, to stir up his son Telemachus, and put courage in his heart.'", "«و من به ایتاکا می‌روم، تا پسرش تلماکوس را برانگیزم و دلیری در دلش بگذارم.»"),
            StoryParagraph("'I will send him to Sparta and to Pylos, to seek news of his father's return, and so win a good name among men.'", "«او را به اسپارتا و پیلوس می‌فرستم تا خبری از بازگشت پدرش بجوید و بدین‌سان نامی نیک در میان مردمان بیابد.»"),
            StoryParagraph("So she spoke, and bound her golden sandals under her feet, immortal, that carry her over the sea and over the boundless land.", "این را گفت و صندل‌های طلایی‌اش را زیر پا بست، جاویدان، که او را بر دریا و بر زمین بی‌کرانه می‌برند."),
            StoryParagraph("And she took her mighty spear, sharp-tipped, with which she conquers the ranks of men, and she went down from Olympus.", "و نیزه نیرومندش را گرفت، تیزپیکان، که با آن صفوف مردمان را می‌شکند و از المپ پایین آمد."),
            StoryParagraph("And she came to Ithaca, and stood at the doorway of Odysseus' house, at the threshold of the court.", "و به ایتاکا رسید و در آستانه خانه اودیسئوس ایستاد، بر آستان حیاط."),
            StoryParagraph("And there she saw the haughty suitors, who were sitting in the hall, playing at dice before the doors, on the hides of oxen they had killed.", "و آنجا خواستگاران متکبر را دید که در تالار نشسته بودند، پیش درها با تاس بازی می‌کردند، بر پوست گاوهایی که کشته بودند."),
            StoryParagraph("And heralds and servants were busy about them, some mixing wine and water in the bowls, others wiping the tables with wet sponges.", "و پیشکاران و خدمتکاران مشغولشان بودند، بعضی شراب و آب را در جام‌ها می‌آمیختند، بعضی میزها را با اسفنج خیس می‌شستند."),
            StoryParagraph("And there she saw Telemachus, godlike in his beauty, sitting among the suitors, with a heavy heart, thinking of his noble father.", "و آنجا تلماکوس را دید، خداشکل در زیبایی‌اش، میان خواستگاران نشسته، با دلی سنگین، به پدر نجیبش می‌اندیشید."),
            StoryParagraph("So Athena came to Ithaca, disguised as Mentes, a friend of the family, and Telemachus saw her first, and went to meet her.", "پس آتنا به ایتاکا آمد، در جامه منتس، دوستی خانوادگی، و تلماکوس نخست او را دید و به پیشوازش رفت."),
        )
    )

    // ─────────── فصل ۲: کالیپسو و دریا ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Calypso and the Sea", titlePersian = "کالیپسو و دریا",
        paragraphs = listOf(
            StoryParagraph("Meanwhile Hermes, the messenger, was speeding over the sea to the island of Calypso.", "در همین حال هرمس، پیام‌آور، بر فراز دریا به سوی جزیره کالیپسو می‌شتافت."),
            StoryParagraph("He skimmed the waves like a sea bird that hunts for fish over the restless deep.", "همچون مرغی دریایی که بر فراز ژرفای بی‌آرام به شکار ماهی می‌رود، بر امواج می‌لغزید."),
            StoryParagraph("And when he reached the island, he went up from the sea to the shore, and came to the great cave where Calypso lived.", "و چون به جزیره رسید، از دریا به ساحل رفت و به غار بزرگ که کالیپسو در آن می‌زیست رسید."),
            StoryParagraph("He found her within, singing in a beautiful voice as she wove at her loom with a golden shuttle.", "او را درون یافت که با آوازی زیبا می‌خواند و با ماکو زرین بر دستگاه بافندگی‌اش می‌بافت."),
            StoryParagraph("A great fire was burning on the hearth, and the smell of cedar and juniper spread far across the island.", "آتشی بزرگ در اجاق می‌سوخت و بوی سدر و ارس تا دوردست جزیره پخش می‌شد."),
            StoryParagraph("Around the cave grew a luxuriant wood of alder and poplar and fragrant cypress.", "گرداگرد غار بیشه‌ای انبوه از توسکا و سپیدار و سرو خوش‌بو روییده بود."),
            StoryParagraph("And a vine, heavy with grapes, spread over the mouth of the cave, and four springs flowed with clear water.", "و تاکی پر از انگور بر دهانه غار گسترده بود و چهار چشمه با آب زلال جاری بود."),
            StoryParagraph("Such was the home of the goddess; and Hermes stood and marveled at the sight.", "این بود خانه الهه؛ و هرمس ایستاد و از آن منظره به شگفت آمد."),
            StoryParagraph("Then he went into the cave, and Calypso, the shining goddess, knew him at once, for gods know one another.", "آنگاه به غار درآمد و کالیپسو، الهه درخشان، بی‌درنگ شناختش، زیرا خدایان یکدیگر را می‌شناسند."),
            StoryParagraph("'Hermes, bearer of the golden wand, why have you come?' she said. 'You have not come before. Speak, whatever your heart desires.'", "گفت: «هرمس، دارنده عصای زرین، چرا آمده‌ای؟ پیش‌تر نیامده بودی. بگو، هر چه دلت می‌خواهد.»"),
            StoryParagraph("So she spoke, and set before him a table with ambrosia, and mixed red nectar.", "این را گفت و پیش او میزی نهاد با آمبروسیا و شهد سرخ را آمیخت."),
            StoryParagraph("And Hermes ate and drank, and then he spoke to her and said:", "و هرمس خورد و نوشید و آنگاه با او سخن گفت و گفت:"),
            StoryParagraph("'Goddess, you ask why I have come. Zeus has sent me against my will, for who would willingly cross such a vast stretch of sea?'", "«ای الهه، می‌پرسی چرا آمده‌ام. زئوس برخلاف میلم فرستاده، زیرا چه کسی به‌رغبت چنین گستره عظیم دریا را می‌پیماید؟»"),
            StoryParagraph("'And there is no city of men nearby where they offer sacrifices to the gods. But no other god may disregard the will of Zeus.'", "«و شهر مردمانی نزدیک نیست که به خدایان قربانی پیشکش کنند. اما هیچ خدای دیگری نمی‌تواند اراده زئوس را نادیده بگیرد.»"),
            StoryParagraph("'Zeus says that you are keeping here the most wretched of men, one of those who fought for nine years around the city of Priam.'", "«زئوس می‌گوید تو اینجا بدبخت‌ترین مردمان را نگه داشته‌ای، یکی از آنان که نُه سال گرد شهر پریام جنگیدند.»"),
            StoryParagraph("'In the tenth year they sacked the city and sailed home; but on the way they sinned against Athena.'", "«در سال دهم شهر را غارت کردند و به خانه بازگشتند؛ اما در راه بر آتنا گناه کردند.»"),
            StoryParagraph("'And she sent a storm that scattered them, and the waves drove him here. Now Zeus commands that you send him home at once.'", "«و او توفانی فرستاد که پراکنده‌شان کرد و امواج او را به اینجا راندند. اکنون زئوس فرمان می‌دهد که بی‌درنگ او را به خانه بفرستی.»"),
            StoryParagraph("'For it is not his fate to perish here, far from his friends. It is destined that he shall see his own people and return to his high-roofed house and his native land.'", "«زیرا تقدیرش این نیست که اینجا هلاک شود، دور از دوستانش. مقدر است که مردم خود را ببیند و به خانه بلندسقف و سرزمین مادری‌اش بازگردد.»"),
            StoryParagraph("So he spoke, and Calypso, the shining goddess, shuddered and spoke to him with winged words:", "این را گفت و کالیپسو، الهه درخشان، لرزید و با او با سخنان بالدار سخن گفت:"),
            StoryParagraph("'Cruel are you gods, and jealous beyond all others, you who begrudge a goddess taking a mortal man openly as her husband.'", "«بی‌رحم‌اید شما خدایان و از همه حسودتر، شما که بر الهه‌ای که آشکارا مردی فانی را شوهر خود کند رشک می‌برید.»"),
            StoryParagraph("'So when Dawn took Orion, you gods begrudged her, until Artemis slew him with her gentle arrows in Ortygia.'", "«چنین بود که چون سپیده اورایون را گرفت، شما خدایان رشک بردید، تا آرتمیس او را با تیرهای لطیفش در اورتیجیا کشت.»"),
            StoryParagraph("'So when Demeter loved Iasion in a thrice-plowed field, Zeus struck him with a blazing thunderbolt.'", "«چنین بود که چون دمتر در کشتزاری سه‌بار شخم‌خورده عاشق یاسیون شد، زئوس او را با آذرخشی شعله‌ور زد.»"),
            StoryParagraph("'And now you begrudge me, gods, that a mortal man should live with me. But I saved him when he was alone on the keel of his ship.'", "«و اکنون شما خدایان بر من رشک می‌برید که مردی فانی با من زندگی کند. اما من نجاتش دادم آنگاه که تنها بر تیرک کشتی‌اش بود.»"),
            StoryParagraph("'For Zeus had struck his swift ship with a blazing thunderbolt and shattered it in the middle of the wine-dark sea.'", "«زیرا زئوس کشتی تندروش را با آذرخشی شعله‌ور زده بود و آن را در میان دریای شراب‌گون خرد کرده بود.»"),
            StoryParagraph("'And all his good comrades perished, but the wind and the wave brought him here. I welcomed him and fed him and loved him.'", "«و همه یاران خوبش هلاک شدند، اما باد و موج او را به اینجا آوردند. پذیرفتمش و خوراکش دادم و دوستش داشتم.»"),
            StoryParagraph("'But since there is no way to thwart the will of Zeus, let him go, if Zeus commands it. But I will not send him, for I have no ship.'", "«اما چون راهی برای ممانعت از اراده زئوس نیست، بگذار برود، اگر زئوس فرمان می‌دهد. اما من نمی‌فرستمش، زیرا کشتی ندارم.»"),
            StoryParagraph("'And I will not give him guides, nor any ship of oars, that might carry him over the wide back of the sea. But I will gladly tell him my counsel, and hide nothing.'", "«و راهنما به او نخواهم داد، نه هیچ کشتی پاروداری که او را بر پشت فراخ دریا ببرد. اما با خوشحالی پندم را به او می‌گویم و چیزی پنهان نمی‌کنم.»"),
            StoryParagraph("Then Hermes answered her: 'Send him now, and beware the wrath of Zeus, lest he be angry with you in the days to come.'", "آنگاه هرمس پاسخش داد: «اکنون بفرستش و از خشم زئوس بترس، مبادا در روزهای آینده بر تو خشم گیرد.»"),
            StoryParagraph("So he spoke and departed, and Calypso, the shining goddess, went to find Odysseus, for she had thought of something better.", "این را گفت و رفت و کالیپسو، الهه درخشان، رفت تا اودیسئوس را بیابد، زیرا به چیزی بهتر اندیشیده بود."),
            StoryParagraph("She found him sitting on the shore, weeping, and his eyes were never dry of tears.", "او را در ساحل نشسته یافت، گریان و چشمانش هرگز از اشک خشک نمی‌شد."),
            StoryParagraph("And his sweet life was ebbing away as he longed for his home and his wife.", "و زندگی شیرینش می‌رفت که تحلیل رود، آنچنان که مشتاق خانه و همسرش بود."),
            StoryParagraph("Calypso came to him and said: 'Unhappy man, do not weep here any longer, for I will send you on your way.'", "کالیپسو به پیشش آمد و گفت: «ای مرد بدبخت، دیگر اینجا گریه نکن، زیرا تو را به راهت خواهم فرستاد.»"),
            StoryParagraph("'Come, cut long timbers with your axe, and build a great raft, with a high deck, that may carry you over the misty sea.'", "«بیا، با تبرت چوب‌های بلند ببر و کلک بزرگی بساز، با عرشه‌ای بلند، که تو را بر دریای مه‌آلود ببرد.»"),
            StoryParagraph("'And I will put bread and water and red wine aboard, to keep you from hunger, and I will clothe you in garments.'", "«و نان و آب و شراب سرخ در آن خواهم گذاشت تا از گرسنگی در امان باشی و تو را جامه خواهم پوشاند.»"),
            StoryParagraph("'And I will send a fair wind behind you, that you may come safely to your own land.'", "«و بادی موافق در پشتت خواهم فرستاد تا به سلامت به سرزمین خودت برسی.»"),
            StoryParagraph("So she spoke, and Odysseus, the godlike, shuddered and answered her with winged words:", "این را گفت و اودیسئوس، خداشکل، لرزید و با سخنان بالدار پاسخش داد:"),
            StoryParagraph("'Goddess, you are planning something other than my safe return, when you bid me cross this great sea on a raft.'", "«ای الهه، تو چیزی جز بازگشت سالم من در سر داری، آنگاه که مرا به پیمودن این دریای بزرگ بر کلکی فرمان می‌دهی.»),
            StoryParagraph("'For not even a well-built ship, with a fair wind behind it, could cross this sea. I will not go on a raft against your will, unless you swear an oath.'", "«زیرا حتی کشتی‌ای خوش‌ساخت با بادی موافق در پشتش نمی‌تواند این دریا را بپیماید. بر کلک نخواهم رفت مگر با خواست تو و سوگندی که بخوری.»"),
            StoryParagraph("So he spoke, and Calypso, the shining goddess, smiled and stroked his hand and said:", "این را گفت و کالیپسو، الهه درخشان، لبخند زد و دستش را نوازش کرد و گفت:"),
            StoryParagraph("'You are truly a man of many ways, and you are not a fool, to plan so carefully for your safety. Hear then my oath.'", "«تو به‌راستی مردی بسیار‌راه‌رفته‌ای و احمق نیستی، که این‌چنین با دقت برای امنیتت نقشه می‌کشی. پس سوگندم را بشنو.»"),
            StoryParagraph("'By the earth and the wide heaven above and the water of the Styx, which is the greatest and most terrible oath of the blessed gods, I will do you no harm.'", "«به زمین و آسمان فراخ بالای سر و آب استوکس، که بزرگ‌ترین و هولناک‌ترین سوگند خدایان سعادتمند است، به تو هیچ آسیبی نخواهم رساند.»"),
            StoryParagraph("'And I will plan for you what I would plan for myself if I were in such need. For my heart is not of iron, but merciful.'", "«و برای تو همان را نقشه می‌کشم که برای خودم اگر در چنین تنگدستی بودم. زیرا دلم از آهن نیست، بلکه رحیم است.»"),
            StoryParagraph("So she spoke, and led the way, and he followed her footsteps, and they came to the cave.", "این را گفت و پیش رفت و او گام‌هایش را دنبال کرد و به غار رسیدند."),
            StoryParagraph("And there he sat down on the same chair from which he had risen, and the goddess set food and drink before him.", "و آنجا بر همان صندلی‌ای نشست که از آن برخاسته بود و الهه خوراک و نوشیدنی پیش او نهاد."),
            StoryParagraph("And he ate and drank, and then Calypso sat opposite him and spoke to him gently.", "و او خورد و نوشید و آنگاه کالیپسو روبه‌رویش نشست و با نرمی با او سخن گفت."),
            StoryParagraph("'So, son of Laertes, you still long to go home to your wife, though she is far less beautiful than I.'", "«پس ای پسر لائرتس، هنوز مشتاق رفتن به خانه پیش همسرت هستی، هرچند او بسیار کم‌زیباتر از من است.»"),
            StoryParagraph("'But if you only knew the hardships that await you, you would stay here with me and share my home.'", "«اما اگر تنها سختی‌هایی را می‌دانستی که در انتظار توست، اینجا با من می‌ماندی و در خانه‌ام شریک می‌شدی.»"),
            StoryParagraph("And Odysseus answered her: 'Goddess, do not be angry with me. I know that Penelope is less beautiful than you.'", "و اودیسئوس پاسخش داد: «ای الهه، بر من خشمگین نشو. می‌دانم پنه‌لوپه از تو کم‌زیباتر است.»"),
            StoryParagraph("'But still, I long to return to my home. And if some god strikes me on the sea, I will endure it, for my heart has long been accustomed to suffering.'", "«اما با این حال، مشتاق بازگشت به خانه‌ام. و اگر خدایی بر دریا زدنم، تحمل خواهم کرد، زیرا دلم دیرزمانی است که به رنج خو کرده است.»"),
            StoryParagraph("So he spoke, and the sun set, and darkness came, and they went to the inner part of the cave and lay together.", "این را گفت و خورشید فرو رفت و تاریکی آمد و به بخش درونی غار رفتند و با هم دراز کشیدند."),
            StoryParagraph("And when dawn came, Odysseus put on his tunic and cloak, and the goddess dressed in a long white robe, and she gave him a great axe and an adze.", "و چون سپیده آمد، اودیسئوس تونیک و شنلش را پوشید و الهه جامه‌ای سفید و بلند پوشید و تبری بزرگ و تیشه‌ای به او داد."),
            StoryParagraph("And he went to the woods and cut down twenty trees, and trimmed them with the axe and smoothed them with the adze.", "و به جنگل رفت و بیست درخت برید و با تبر شاخ‌وبرگشان را زد و با تیشه صافشان کرد."),
            StoryParagraph("And Calypso brought him augers, and he bored through all the timbers and fitted them together with pegs and joints.", "و کالیپسو مته‌هایی برایش آورد و همه چوب‌ها را سوراخ کرد و با میخ و مفصل به هم جفت کرد."),
            StoryParagraph("And he built a deck and set a mast and a yard upon it, and made a rudder, and fenced the sides with willow to keep out the waves.", "و عرشه‌ای ساخت و دکل و یاردی بر آن نهاد و سکانی ساخت و کناره‌ها را با بید حصار کرد تا امواج را بازدارد."),
            StoryParagraph("And Calypso brought him cloth for sails, and he made them, and fastened them with ropes, and used levers to raise the mast.", "و کالیپسو برایش پارچه‌ای برای بادبان آورد و بادبان‌ها را ساخت و با طناب بست و با اهرم دکل را برافراشت."),
            StoryParagraph("And he put the raft on rollers and launched it into the sea, and loaded it with food and drink and clothing.", "و کلک را بر غلتک‌ها نهاد و به دریا انداخت و آن را با خوراک و نوشیدنی و جامه بار کرد."),
            StoryParagraph("And Calypso sent a fair wind behind him, and he spread his sails and sat at the helm and steered with skill.", "و کالیپسو بادی موافق در پشتش فرستاد و بادبان‌ها را گشود و بر سکان نشست و با مهارت راند."),
            StoryParagraph("And he sailed for seventeen days, and on the eighteenth he saw the shadowy mountains of the Phaeacian land.", "و هفده روز دریانوردی کرد و در روز هجدهم کوه‌های سایه‌گون سرزمین فایاسیایی را دید."),
            StoryParagraph("But Poseidon, returning from the Ethiopians, saw him from the mountains of the Solymi, and his heart was filled with anger.", "اما پوزئیدون، در بازگشت از اتیوپیایی‌ها، او را از کوه‌های سولیما دید و دلش پر از خشم شد."),
            StoryParagraph("'So the gods have changed their minds about Odysseus while I was away,' he said, and he gathered the clouds and stirred the sea with his trident.", "گفت: «پس خدایان در غیاب من درباره اودیسئوس تغییر عقیده داده‌اند.» و ابرها را گرد آورد و دریا را با نیزه سه‌شاخه‌اش برآشفت."),
            StoryParagraph("And he roused all the blasts of all the winds, and covered land and sea with clouds, and night rushed down from heaven.", "و همه دم‌های همه بادها را برانگیخت و خشکی و دریا را با ابر پوشاند و شب از آسمان فرو ریخت."),
            StoryParagraph("And the winds blew together, and the sea rose, and Odysseus' knees and heart failed him, and he spoke to his great heart in sorrow:", "و بادها با هم وزیدند و دریا برخاست و زانوها و دل اودیسئوس فرو ریخت و در اندوه با دل بزرگش سخن گفت:"),
            StoryParagraph("'Wretched man that I am! What will become of me now? I fear that Calypso spoke truly when she said I would suffer much before I reached my home.'", "«ای مرد بدبخت! اکنون چه بر سرم خواهد آمد؟ می‌ترسم کالیپسو راست گفته باشد که گفت پیش از رسیدن به خانه‌ام رنج بسیار خواهم کشید.»"),
            StoryParagraph("And even as he spoke, a great wave struck him, and it whirled the raft round and round, and he fell far from it into the sea.", "و همانطور که سخن می‌گفت، موجی بزرگ بر او زد و کلک را دور خود چرخاند و او دور از آن به دریا افتاد."),
            StoryParagraph("And the mast broke, and the sails and the yard fell into the sea, and he was held under the water for a long time.", "و دکل شکست و بادبان‌ها و یارد به دریا افتادند و او دیرزمانی زیر آب نگه داشته شد."),
            StoryParagraph("And at last he rose to the surface and spat the bitter brine from his mouth, and the waves tossed him to and fro.", "و سرانجام به سطح آب آمد و آب شور تلخ را از دهانش بیرون انداخت و امواج او را این‌سو و آن‌سو پرتاب می‌کردند."),
            StoryParagraph("But Ino, the white goddess, who had been a mortal woman and now had a place among the sea nymphs, saw him and pitied him.", "اما اینو، الهه سفید، که زنی فانی بود و اکنون میان پریان دریا جایی داشت، او را دید و بر او رحم آورد."),
            StoryParagraph("She rose from the water like a gull and sat on the raft and said: 'Unhappy man, why does Poseidon hate you so? He shall not destroy you, however much he wishes.'", "همچون مرغ دریایی از آب برخاست و بر کلک نشست و گفت: «ای مرد بدبخت، چرا پوزئیدون این‌گونه از تو بدش می‌آید؟ هرچند که بخواهد، نابودت نخواهد کرد.»"),
            StoryParagraph("'Take this veil and bind it under your chest, and do not fear death or anything else. And when you reach the shore, unbind it and throw it into the sea.'", "«این حجاب را بگیر و زیر سینه‌ات ببند و از مرگ یا چیز دیگری نترس. و چون به ساحل رسیدی، بازش کن و به دریا بیندازش.»"),
            StoryParagraph("And she gave him the veil and plunged back into the sea, and the great wave took him and carried him toward the rocky shore.", "و حجاب را به او داد و به دریا فرو رفت و موج بزرگ او را گرفت و به ساحل صخره‌ای برد."),
            StoryParagraph("And he swam for two days and two nights, and on the third dawn he saw the land, and he swam toward it with all his strength.", "و دو روز و دو شب شنا کرد و در سپیده سوم خشکی را دید و با تمام نیرو به سویش شنا کرد."),
            StoryParagraph("But the shore was rocky and cruel, and he clung to a rock and was torn by the waves, and he thought he would die.", "اما ساحل صخره‌ای و بی‌رحم بود و به صخره‌ای چنگ زد و امواج پاره‌اش کردند و گمان کرد خواهد مرد."),
            StoryParagraph("At last he found the mouth of a river, and he prayed to the god of the river, and the god heard him and calmed the water and let him reach the shore.", "سرانجام دهانه رودی را یافت و به خدای رود دعا کرد و خدا شنیدش و آب را آرام کرد و گذاشت به ساحل برسد."),
            StoryParagraph("And he crawled onto the land and kissed the earth, and he lay there gasping, and he did not know if he was alive or dead.", "و به خشکی خزید و زمین را بوسید و آنجا دراز کشید نفس‌نفس‌زنان و نمی‌دانست زنده است یا مرده."),
            StoryParagraph("And he found two olive bushes growing together, and he crept beneath them, and covered himself with leaves, and slept.", "و دو درخت زیتون یافت که با هم روییده بودند و زیرشان خزید و خود را با برگ پوشاند و خوابید."),
            StoryParagraph("And Athena, the bright-eyed goddess, came to him and put sleep in his eyes, that he might rest, and she went to the city of the Phaeacians to prepare his welcome.", "و آتنا، الهه روشن‌چشم، به پیشش آمد و خواب در چشمانش نهاد تا بیاساید و به شهر فایاسیایی‌ها رفت تا مقدمش را آماده کند."),
        )
    )

    // ─────────── فصل ۳: سیکلوپ پولیفموس ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Cyclops Polyphemus", titlePersian = "سیکلوپ پولیفموس",
        paragraphs = listOf(
            StoryParagraph("From the land of the Lotus-Eaters we sailed, grieving at heart, and came to the land of the Cyclopes.", "از سرزمین نیلوفرخواران دریانوردی کردیم، در دل غمگین و به سرزمین سیکلوپ‌ها رسیدیم."),
            StoryParagraph("A lawless and savage race they are, who trust in the immortal gods, and plant no crops with their hands.", "نژادی بی‌قانون و وحشی‌اند، که به خدایان جاوید توکل می‌کنند و با دست خود کشت نمی‌کارند."),
            StoryParagraph("They live in hollow caves on the mountain tops, and each one rules his own wife and children, and cares not for the others.", "در غارهای توخالی بر قله کوه‌ها زندگی می‌کنند و هر یک بر زن و فرزندان خود فرمان می‌راند و به دیگران کاری ندارد."),
            StoryParagraph("Now there was a fertile island lying off their shore, not far from the land of the Cyclopes.", "اکنون جزیره‌ای حاصلخیز در نزدیکی ساحلشان بود، نه چندان دور از سرزمین سیکلوپ‌ها."),
            StoryParagraph("It was covered with wild goats, and no man lived there, and no hunters came, and no shepherds.", "پوشیده از بزهای وحشی بود و هیچ‌کس آنجا زندگی نمی‌کرد و نه شکارچیانی می‌آمدند و نه چوپانی."),
            StoryParagraph("So the Cyclopes had no ships, and could not cross over, and the island remained untouched, a haven for wild goats.", "پس سیکلوپ‌ها کشتی نداشتند و نمی‌توانستند بگذرند و جزیره دست‌نخورده ماند، پناهگاهی برای بزهای وحشی."),
            StoryParagraph("There we anchored, and some god guided us through the darkness, for it was night and we could not see.", "آنجا لنگر انداختیم و خدایی ما را در تاریکی راهنمایی کرد، زیرا شب بود و نمی‌دیدیم."),
            StoryParagraph("And we slept on the shore until the dawn, and when dawn came, we wandered about the island and marveled.", "و تا سپیده در ساحل خوابیدیم و چون سپیده آمد، در جزیره گشتیم و شگفت‌زده شدیم."),
            StoryParagraph("And the nymphs, the daughters of Zeus, sent the wild goats up to us, and we killed many, and feasted.", "و پریان، دختران زئوس، بزهای وحشی را به سوی ما فرستادند و بسیاری کشتیم و ضیافت کردیم."),
            StoryParagraph("So we sat all day till sunset, eating meat and drinking wine, for there was still wine left from our ships.", "تمام روز تا غروب نشستیم و گوشت خوردیم و شراب نوشیدیم، زیرا هنوز شرابی از کشتی‌هایمان باقی بود."),
            StoryParagraph("And we saw the land of the Cyclopes near, with smoke rising from their caves, and we heard their voices and their flocks.", "و سرزمین سیکلوپ‌ها را نزدیک دیدیم، با دود برخاسته از غارهایشان و صدایشان و گله‌هایشان را شنیدیم."),
            StoryParagraph("Then I spoke to my men and said: 'Stay here, my friends, while I go with my own ship and my own crew to see what men live there.'", "آنگاه با یارانم سخن گفتم و گفتم: «ای دوستان، اینجا بمانید تا من با کشتی و خدمه خودم بروم و ببینم چه مردمانی آنجا زندگی می‌کنند.»"),
            StoryParagraph("So I spoke, and I took my ship and my crew, and we sailed to the land of the Cyclopes.", "این را گفتم و کشتی و خدمه‌ام را برداشتم و به سرزمین سیکلوپ‌ها دریانوردی کردیم."),
            StoryParagraph("And when we reached the shore, we saw a cave near the sea, high up, with laurels growing round it.", "و چون به ساحل رسیدیم، غاری نزدیک دریا دیدیم، بالا، با برگ‌های غار گرداگردش."),
            StoryParagraph("There were many flocks of sheep and goats sleeping in it, and a courtyard with a wall of stone and tall pines and oaks.", "گله‌های بسیاری از گوسفند و بز در آن خوابیده بودند و حیاطی با دیوار سنگی و کاج‌ها و بلوط‌های بلند."),
            StoryParagraph("And in the cave lived a giant, a Cyclops, who pastured his flocks alone, far from others, and knew no law.", "و در غار غولی زندگی می‌کرد، سیکلوپی، که گله‌هایش را تنها می‌چراند، دور از دیگران و قانونی نمی‌شناخت."),
            StoryParagraph("He was a monster, not like a man who eats bread, but like a wooded peak of high mountains, standing alone.", "هیولایی بود، نه مانند مردی که نان می‌خورد، بلکه مانند قلعه‌ای جنگلی از کوه‌های بلند، تنها ایستاده."),
            StoryParagraph("I took twelve of my best men and a goatskin of dark sweet wine, and we went up to the cave.", "دوازده تن از بهترین یارانم و مشک بزی از شراب شیرین تیره برداشتم و به غار رفتیم."),
            StoryParagraph("But the Cyclops was not at home; he was pasturing his flocks in the fields, so we went into the cave and looked around.", "اما سیکلوپ در خانه نبود؛ در چراگاه گله‌هایش را می‌چراند، پس به غار درآمدیم و گشتیم."),
            StoryParagraph("And there were baskets full of cheeses, and pens full of lambs and kids, and vessels full of milk and whey.", "و سبدهایی پر از پنیر و آغول‌هایی پر از بره و بزغاله و ظرف‌هایی پر از شیر و مایع پنیر بود."),
            StoryParagraph("And my men begged me to take some cheeses and lambs and kids and go back to the ship.", "و یارانم التماس کردند چند پنیر و بره و بزغاله برداریم و به کشتی بازگردیم."),
            StoryParagraph("But I would not listen, though it would have been better, for I wanted to see the Cyclops and find out if he would give me gifts of hospitality.", "اما گوش نکردم، هرچند بهتر بود، زیرا می‌خواستم سیکلوپ را ببینم و بفهمم آیا هدیه مهمان‌نوازی به من خواهد داد."),
            StoryParagraph("So we lit a fire and made an offering and ate some cheese, and we waited for him to come.", "پس آتشی افروختیم و قربانی کردیم و کمی پنیر خوردیم و منتظر ماندیم تا بیاید."),
            StoryParagraph("And he came at evening, driving his flocks, and he threw down a great bundle of wood for his fire.", "و هنگام غروب آمد، گله‌هایش را می‌راند و بسته‌ای بزرگ از چوب برای آتشش افکند."),
            StoryParagraph("And we hid in the cave, in fear, when we saw him, and he drove his flocks inside, all that he milked, but he left the males outside.", "و در غار پنهان شدیم، از ترس، چون دیدیمش و او گله‌هایش را به درون راند، همه آنانی که می‌دوشید، اما نرها را بیرون گذاشت."),
            StoryParagraph("And then he lifted a great stone and set it in the doorway, a stone so huge that two-and-twenty wagons could not move it.", "و آنگاه سنگی بزرگ برداشت و در آستانه در نهاد، سنگی چنان عظیم که بیست و دو گاری نمی‌توانستند تکانش دهند."),
            StoryParagraph("And he milked the sheep and the goats, and put the young under each mother, and then he lit a fire and saw us.", "و گوسفندان و بزها را دوشید و بچه‌ها را زیر هر مادر نهاد و آنگاه آتشی افروخت و ما را دید."),
            StoryParagraph("'Strangers, who are you?' he said. 'Where do you come from over the watery ways? Are you traders, or are you wandering pirates?'", "گفت: «ای بیگانگان، شما کیستید؟ از کجا از راه‌های آبی می‌آیید؟ بازرگانید یا دزدان دریایی سرگردان؟»"),
            StoryParagraph("So he spoke, and our hearts were broken with fear, for his voice was terrible and he was huge.", "این را گفت و دل‌هایمان از ترس خرد شد، زیرا صدایش هولناک بود و او عظیم."),
            StoryParagraph("But I answered him and said: 'We are Achaeans, from Troy, driven off course by the winds over the great sea.'", "اما پاسخش دادم و گفتم: «ما آخایی هستیم، از تروا، که بادها ما را بر دریای بزرگ از مسیر راندند.»"),
            StoryParagraph("'And we are returning home, but we have been driven far from our course. And we are suppliants of Zeus, who protects strangers.'", "«و به خانه بازمی‌گردیم اما بسیار از مسیرمان دور افتاده‌ایم. و ما التماس‌کنندگان زئوس هستیم، که از بیگانگان حمایت می‌کند.»"),
            StoryParagraph("So I spoke, and he answered me with a cruel heart: 'You are a fool, stranger, or you have come from far, to tell me to fear the gods.'", "این را گفتم و او با دلی بی‌رحم پاسخم داد: «احمقی، ای بیگانه، یا از دور آمده‌ای که به من می‌گویی از خدایان بترسم.»"),
            StoryParagraph("'For we Cyclopes do not care for Zeus or the blessed gods, for we are stronger. But tell me, where is your ship?'", "«زیرا ما سیکلوپ‌ها به زئوس و خدایان سعادتمند اهمیت نمی‌دهیم، زیرا نیرومندتریم. اما بگو، کشتی‌ات کجاست؟»"),
            StoryParagraph("So he spoke, and I answered him with a crafty heart: 'Poseidon, the earth-shaker, shattered my ship against the rocks, and I and these men alone escaped.'", "این را گفت و من با دلی حیله‌گر پاسخش دادم: «پوزئیدون، زمین‌جنبان، کشتی‌ام را بر صخره‌ها خرد کرد و تنها من و این مردان جان به سلامت بردیم.»"),
            StoryParagraph("So I spoke, and he said nothing, but sprang up and seized two of my men and dashed them to the ground like puppies.", "این را گفتم و او چیزی نگفت، بلکه برجست و دو تن از یارانم را گرفت و همچون توله‌سگ بر زمین کوفت."),
            StoryParagraph("And their brains ran out on the floor, and he tore them limb from limb and made his meal, eating them like a mountain lion.", "و مغزشان بر زمین ریخت و اندام‌به‌اندام پاره‌شان کرد و غذایش ساخت، همچون شیر کوهی خوردشان."),
            StoryParagraph("And we wept and prayed to Zeus, but there was nothing we could do, for our hearts were frozen with fear.", "و گریستیم و به زئوس دعا کردیم اما هیچ نمی‌توانستیم کرد، زیرا دل‌هایمان از ترس یخ زده بود."),
            StoryParagraph("And when he had eaten, he lay down among his sheep, and slept. And I thought of drawing my sword and stabbing him in the chest.", "و چون خورد، میان گوسفندانش دراز کشید و خوابید. و من اندیشیدم شمشیرم را بکشم و در سینه‌اش فرو کنم."),
            StoryParagraph("But I held back, for we would have perished there, since we could not move the stone from the doorway.", "اما بازایستادم، زیرا آنجا هلاک می‌شدیم، چون نمی‌توانستیم سنگ را از آستانه در تکان دهیم."),
            StoryParagraph("So we waited, groaning and grieving, until the dawn came. And when dawn came, he lit the fire and milked his flocks.", "پس منتظر ماندیم، ناله‌کنان و غمگین، تا سپیده آمد. و چون سپیده آمد، آتش افروخت و گله‌هایش را دوشید."),
            StoryParagraph("And he seized two more of my men and ate them, and then he drove his flocks out, and put the stone back in the doorway.", "و دو تن دیگر از یارانم را گرفت و خوردشان و آنگاه گله‌هایش را بیرون راند و سنگ را به آستانه در بازگرداند."),
            StoryParagraph("And I was left with the others, planning how to take revenge, if Athena would grant it.", "و من با دیگران ماندم و نقشه انتقام می‌کشیدم، اگر آتنا اجازه می‌داد."),
            StoryParagraph("And I thought of a plan. There was a club of green olive wood in the cave, which the Cyclops had cut to use when it dried.", "و نقشه‌ای اندیشیدم. در غار چماقی از چوب زیتون سبز بود که سیکلوپ بریده بود تا چون خشک شود به کارش برد."),
            StoryParagraph("It was as big as the mast of a ship, and we cut off a fathom's length and sharpened it to a point.", "به بزرگی دکل کشتی بود و به اندازه‌ای یک fathom بریدیم و نوکش را تیز کردیم."),
            StoryParagraph("And we hardened it in the fire, and hid it under the dung, and then we cast lots to see who would help me.", "و در آتش سختش کردیم و زیر سرگین پنهانش کردیم و آنگاه قرعه انداختیم تا ببینیم چه کسانی به من کمک می‌کنند."),
            StoryParagraph("The lot fell to the four I would have chosen myself, and there were five of us in all.", "قرعه بر آن چهار تن افتاد که خودم انتخاب می‌کردم و در کل پنج تن بودیم."),
            StoryParagraph("And at evening he came, driving his flocks, and again he seized two men and ate them.", "و هنگام غروب آمد، گله‌هایش را می‌راند و باز دو مرد گرفت و خوردشان."),
            StoryParagraph("Then I stood before him with an ivy-wood bowl of the dark wine and said: 'Cyclops, take this and drink, since you have eaten human flesh.'", "آنگاه با جامی چوبی از پیچک پر از شراب تیره پیشش ایستادم و گفتم: «ای سیکلوپ، این را بگیر و بنوش، چون گوشت آدمی خورده‌ای.»"),
            StoryParagraph("'So you may know what kind of wine we had on our ship. And I was bringing it to you as a gift, in hope that you would send me home.'", "«تا بدانی در کشتی‌مان چه شرابی داشتیم. و آن را برایت هدیه می‌آوردم، به امید آنکه مرا به خانه بفرستی.»"),
            StoryParagraph("So I spoke, and he took it and drank it, and was pleased, and asked for more.", "این را گفتم و او گرفت و نوشید و خوشش آمد و بیشتر خواست."),
            StoryParagraph("'Give me more, and tell me your name, so I may give you a gift that will please you,' he said.", "گفت: «بیشتر بده و نامت را بگو تا هدیه‌ای دهم که خوشحت کند.»"),
            StoryParagraph("And I gave him more, three times, and he drank it all, and the wine overcame him, and he fell back and slept.", "و سه بار بیشترش دادم و او همه را نوشید و شراب بر او چیره شد و به عقب افتاد و خوابید."),
            StoryParagraph("Then I said to him: 'Cyclops, you ask my name. My name is Nobody. Nobody is what my mother and father call me, and all my friends.'", "آنگاه به او گفتم: «ای سیکلوپ، نامم را می‌پرسی. نام من هیچ‌کس است. هیچ‌کس نامی است که مادر و پدرم و همه دوستانم مرا می‌خوانند.»"),
            StoryParagraph("So I spoke, and he answered: 'Then I will eat Nobody last of all his friends, and the others first. That is my gift to you.'", "این را گفتم و او پاسخ داد: «پس هیچ‌کس را آخر از همه دوستانش خواهم خورد و دیگران را اول. این هدیه من به توست.»"),
            StoryParagraph("And he fell back, and vomited wine and human flesh, and lay in a drunken sleep.", "و به عقب افتاد و شراب و گوشت آدمی را قی کرد و در خوابی مستانه دراز کشید."),
            StoryParagraph("Then I put the stake in the fire and heated it until it glowed, and my men and I took it and drove it into his eye.", "آنگاه چماق را در آتش نهادم و تا سرخ شد گرمش کردم و من و یارانم آن را گرفتیم و در چشمانش فرو کردیم."),
            StoryParagraph("And I leaned on it and twisted it, as a man twists a drill when boring a ship's timber, and the blood boiled round it.", "و بر آن تکیه کردم و چرخاندم، همانطور که مردی مته را می‌چرخاند چون چوب کشتی را سوراخ می‌کند و خون گردش جوشید."),
            StoryParagraph("And he screamed, and the cave echoed with his cry, and we drew back in fear.", "و فریاد کشید و غار از فریادش پیچید و ما از ترس عقب کشیدیم."),
            StoryParagraph("And he pulled the stake from his eye, all blood, and threw it from him, and called to the other Cyclopes who lived nearby.", "و چماق را از چشمانش بیرون کشید، غرق خون، و از خود دورش انداخت و دیگر سیکلوپ‌های نزدیک را فرا خواند."),
            StoryParagraph("And they came and stood outside the cave and asked: 'What is wrong, Polyphemus? Why do you call us in the night? Is someone killing you?'", "و آمدند و بیرون غار ایستادند و پرسیدند: «چه شده، پولیفموس؟ چرا شبانه ما را می‌خوانی؟ کسی می‌کشدت؟»"),
            StoryParagraph("And he answered from inside the cave: 'Nobody is killing me! Nobody has tricked me!'", "و او از درون غار پاسخ داد: «هیچ‌کس مرا می‌کشد! هیچ‌کس فریبم داده!»"),
            StoryParagraph("And they answered: 'Then if nobody is hurting you, it must be a sickness from Zeus, and we cannot help. Pray to your father Poseidon.'", "و پاسخ دادند: «پس اگر هیچ‌کس آزارت نمی‌دهد، باید بیماری‌ای از زئوس باشد و ما نمی‌توانیم کمک کنیم. به پدرت پوزئیدون دعا کن.»"),
            StoryParagraph("And they went away, and my heart laughed, for my trick had deceived them.", "و رفتند و دلم خندید، زیرا حیله‌ام فریبشان داده بود."),
            StoryParagraph("But the Cyclops groaned and felt for the stone and moved it from the door, and sat in the doorway with his hands outstretched.", "اما سیکلوپ نالید و سنگ را لمس کرد و از در برداشت و در آستانه در نشست با دستان گشوده."),
            StoryParagraph("And he tried to catch anyone who went out with the sheep, but I thought of a better plan.", "و تلاش کرد هر که با گوسفندان بیرون می‌رود بگیرد، اما من به نقشه‌ای بهتر اندیشیدم."),
            StoryParagraph("I tied the sheep together in threes, and under each middle one I tied a man, and on either side a sheep walked.", "گوسفندان را سه‌تا سه‌تا بستم و زیر هر وسطی مردی بستم و هر دو طرف گوسفندی راه می‌رفت."),
            StoryParagraph("And for myself I chose the greatest ram of all, and I clung under his belly, in his thick wool, and waited.", "و برای خودم بزرگ‌ترین قوچ را برگزیدم و زیر شکمش چنگ زدم، در پشم انبوهش و منتظر ماندم."),
            StoryParagraph("And when dawn came, the sheep went out to pasture, and the ram went last, heavy with wool and with me.", "و چون سپیده آمد، گوسفندان به چراگاه رفتند و قوچ آخر رفت، سنگین از پشم و از من."),
            StoryParagraph("And the Cyclops felt the ram's back and said: 'Dear ram, why are you last today? You always went first before.'", "و سیکلوپ پشت قوچ را لمس کرد و گفت: «ای قوچ عزیز، چرا امروز آخر شده‌ای؟ پیش‌تر همیشه اول می‌رفتی.»"),
            StoryParagraph("'Are you grieving for your master's eye, which Nobody put out? But if you could speak, you would tell me where he is hiding.'", "«آیا برای چشم اربابت که هیچ‌کس کورش کرد غمگینی؟ اما اگر می‌توانستی سخن بگویی، می‌گفتی کجا پنهان شده است.»"),
            StoryParagraph("So he spoke, and let the ram go, and we escaped from the cave, and hurried to our ship.", "این را گفت و قوچ را رها کرد و ما از غار گریختیم و به کشتی‌مان شتافتیم."),
            StoryParagraph("And we took the sheep aboard and set sail, and when we were far out, I shouted to the Cyclops.", "و گوسفندان را سوار کردیم و بادبان کشیدیم و چون دور شدیم، بر سیکلوپ فریاد زدم."),
            StoryParagraph("'Cyclops, you were not to escape the wrath of Zeus, for you have eaten your guests in your own house.'", "«ای سیکلوپ، از خشم زئوس نمی‌توانستی بگریزی، زیرا مهمانانت را در خانه خودت خوردی.»"),
            StoryParagraph("And he broke off a peak of the mountain and threw it at us, but it fell short of the ship.", "و قلعه‌ای از کوه را کند و به سوی ما انداخت اما کوتاه‌تر از کشتی افتاد."),
            StoryParagraph("And I shouted again: 'If anyone asks you who blinded you, say Odysseus, son of Laertes, of Ithaca.'", "و باز فریاد زدم: «اگر کسی پرسید چه کسی کورت کرد، بگو اودیسئوس، پسر لائرتس، از ایتاکا.»"),
            StoryParagraph("And he prayed to Poseidon: 'Father, if I am yours, grant that Odysseus never reach his home. Or if he must, let him come late, alone, in a stranger's ship, and find trouble in his house.'", "و به پوزئیدون دعا کرد: «پدر، اگر از آنِ توام، بگذار اودیسئوس هرگز به خانه‌اش نرسد. یا اگر باید، دیر برسد، تنها، در کشتی بیگانه و در خانه‌اش گرفتاری بیابد.»"),
            StoryParagraph("And Poseidon heard his prayer, and from that day he was angry with Odysseus, and troubled all his ways.", "و پوزئیدون دعایش را شنید و از آن روز بر اودیسئوس خشمگین شد و همه راه‌هایش را پر از گرفتاری کرد."),
        )
    )

    // ─────────── فصل ۴: کیرکه جادوگر ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Circe the Enchantress", titlePersian = "کیرکه جادوگر",
        paragraphs = listOf(
            StoryParagraph("From the land of the Cyclopes we came to the island of Aeolus, the keeper of the winds.", "از سرزمین سیکلوپ‌ها به جزیره آیولوس، نگهبان بادها رسیدیم."),
            StoryParagraph("And Aeolus gave me a bag made of the skin of an ox, in which he had bound all the winds.", "و آیولوس کیسه‌ای از پوست گاو به من داد که در آن همه بادها را بسته بود."),
            StoryParagraph("For Zeus had made him the keeper of the winds, to calm or rouse them as he pleased.", "زیرا زئوس او را نگهبان بادها کرده بود تا هرگونه که بخواهد آرامشان کند یا برانگیزد."),
            StoryParagraph("And he bound the bag with a silver cord, so that not even a breath could escape.", "و کیسه را با ریسمانی نقره‌ای بست، چنان که حتی نفسی نمی‌توانست بگریزد."),
            StoryParagraph("But he left the west wind free, to blow us homeward, and he gave us a fair voyage.", "اما باد غربی را آزاد گذاشت تا ما را به خانه ببرد و سفر خوشی به ما داد."),
            StoryParagraph("For nine days and nine nights we sailed, and on the tenth we saw the shores of Ithaca.", "نُه روز و نُه شب دریانوردی کردیم و در روز دهم سواحل ایتاکا را دیدیم."),
            StoryParagraph("And we could see the men tending the fires upon the shore, so near we were to home.", "و می‌توانستیم مردانی را ببینیم که بر ساحل آتش می‌افروختند، اینقدر به خانه نزدیک بودیم."),
            StoryParagraph("But then I fell asleep, for I was weary with steering, and my comrades began to talk among themselves.", "اما آنگاه به خواب رفتم، زیرا از سکان‌داری خسته بودم و یارانم میان خود شروع به صحبت کردند."),
            StoryParagraph("They thought the bag contained gold and silver, gifts from Aeolus, and they envied me.", "گمان کردند کیسه حاوی طلا و نقره است، هدایایی از آیولوس و بر من رشک بردند."),
            StoryParagraph("And they opened the bag, and all the winds rushed out, and a storm seized us and swept us back to the sea.", "و کیسه را گشودند و همه بادها بیرون ریختند و توفانی ما را گرفت و به دریا بازگرداند."),
            StoryParagraph("And I woke and saw the land receding, and I wept, and I thought of throwing myself into the sea.", "و بیدار شدم و دیدم خشکی دور می‌شود و گریستم و اندیشیدم خود را به دریا افکنم."),
            StoryParagraph("But I endured it, and we sailed back to Aeolus, and I went to his house and asked for help.", "اما تحمل کردم و به آیولوس بازگشتیم و به خانه‌اش رفتم و کمک خواستم."),
            StoryParagraph("But he drove me from his door, saying: 'Get out quickly, most hateful of men. It is not right for me to help a man the gods hate.'", "اما مرا از درش راند و گفت: «زود بیرون برو، منفورترین مردمان. درست نیست که به مردی که خدایان از او بدشان می‌آید کمک کنم.»"),
            StoryParagraph("So we sailed on, grieving, and our hearts were heavy with weariness, and our own folly had ruined us.", "پس با اندوه دریانوردی کردیم و دل‌هایمان از خستگی سنگین بود و حماقت خودمان نابودمان کرده بود."),
            StoryParagraph("For six days and nights we sailed, and on the seventh we came to the land of the Laestrygonians, where the paths of day and night are near.", "شش روز و شب دریانوردی کردیم و در هفتم به سرزمین لایستریگونی‌ها رسیدیم، جایی که راه‌های روز و شب نزدیک‌اند."),
            StoryParagraph("And there a shepherd driving in his flock greets another driving out, and a man could earn double wages if he could work without sleep.", "و آنجا چوپانی که گله‌اش را می‌راند به چوپانی دیگر که گله‌اش را بیرون می‌برد سلام می‌کند و مردی می‌توانست دو مزد بگیرد اگر بی‌خواب کار می‌کرد."),
            StoryParagraph("And we came to a harbor with steep cliffs on both sides, and a narrow entrance, and the other ships went in.", "و به بندری رسیدیم با صخره‌های بلند در دو طرف و ورودی‌ای تنگ و دیگر کشتی‌ها به درون رفتند."),
            StoryParagraph("But I kept my ship outside, tied to a rock, and from there I climbed a cliff and looked around.", "اما من کشتی‌ام را بیرون نگه داشتم، به صخره‌ای بسته و از آنجا از صخره‌ای بالا رفتم و اطراف را نگریستم."),
            StoryParagraph("And I saw no fields of men, but smoke rising from the land, and I sent men to see who lived there.", "و کشتزار مردمانی ندیدم، اما دودی دیدم که از زمین برمی‌خاست و مردانی فرستادم تا ببینند چه کسانی آنجا زندگی می‌کنند."),
            StoryParagraph("And they met a giant maiden, the daughter of Antiphates, the king, and she led them to her father's house.", "و با دوشیزه‌ای غول‌آسا دیدار کردند، دختر آنتیفاتس، پادشاه و او آنان را به خانه پدرش برد."),
            StoryParagraph("And the king seized one of my men and devoured him, and the others fled, and the king raised a cry.", "و پادشاه یکی از یارانم را گرفت و بلعید و دیگران گریختند و پادشاه فریادی برکشید."),
            StoryParagraph("And the Laestrygonians came from all sides, countless, and they threw rocks at the ships and broke them.", "و لایستریگونی‌ها از هر سو آمدند، بی‌شمار و سنگ به کشتی‌ها انداختند و خردشان کردند."),
            StoryParagraph("And they speared the men like fish, and carried them off to eat, and the harbor was filled with death.", "و مردان را همچون ماهی نیزه زدند و برای خوردن بردند و بندر پر از مرگ شد."),
            StoryParagraph("But I drew my sword and cut the cable of my ship, and we escaped, and my ship alone survived.", "اما شمشیرم را کشیدم و بند کشتی‌ام را بریدم و گریختیم و تنها کشتی من جان به سلامت برد."),
            StoryParagraph("So we came to the island of Aeaea, where Circe lived, the fair-haired goddess, sister of Aeetes.", "پس به جزیره آیایا رسیدیم، جایی که کیرکه، الهه خوش‌مو، خواهر آیتس می‌زیست."),
            StoryParagraph("And we lay two days and nights on the shore, and on the third I climbed a rocky hill and looked around.", "و دو روز و شب در ساحل خوابیدیم و در سومین از تپه‌ای سنگی بالا رفتم و اطراف را نگریستم."),
            StoryParagraph("And I saw smoke rising from the halls of Circe, through the woods and the thickets.", "و دودی دیدم که از تالارهای کیرکه برمی‌خاست، از میان جنگل و بیشه."),
            StoryParagraph("And I thought of going to see, and on my way back I met a great stag, and I killed it with my spear.", "و اندیشیدم بروم و ببینم و در راه بازگشت به گوزنی بزرگ برخوردم و با نیزه‌ام کشتمش."),
            StoryParagraph("And I carried it to the ship, and we ate, and drank, and slept by the shore until dawn.", "و به کشتی بردمش و خوردیم و نوشیدیم و تا سپیده در ساحل خوابیدیم."),
            StoryParagraph("And when dawn came, I divided my men into two groups, and I led one and Eurylochus the other.", "و چون سپیده آمد، یارانم را به دو گروه تقسیم کردم و من یکی را رهبری کردم و اوریلوخوس دیگری را."),
            StoryParagraph("And we cast lots, and the lot fell to Eurylochus to go with twenty-two men to explore the island.", "و قرعه انداختیم و قرعه بر اوریلوخوس افتاد که با بیست و دو مرد به کاوش جزیره برود."),
            StoryParagraph("And they found the house of Circe in a clearing, built of polished stone, with wolves and lions around it.", "و خانه کیرکه را در پاکشی یافتند، از سنگ صیقلی ساخته شده، با گرگ‌ها و شیرها گرداگردش."),
            StoryParagraph("And the beasts were gentle, for Circe had enchanted them, and they fawned on my men like dogs on their master.", "و جانوران ملایم بودند، زیرا کیرکه افسونشان کرده بود و همچون سگان بر اربابشان به یارانم نوازش می‌کردند."),
            StoryParagraph("And my men heard a sweet voice singing within, and they called out, and Circe came and opened the doors.", "و یارانم آوازی شیرین از درون شنیدند و صدا زدند و کیرکه آمد و درها را گشود."),
            StoryParagraph("And she invited them in, and they followed, all except Eurylochus, who stayed outside, fearing a trick.", "و دعوتشان کرد به درون و آنان پیروی کردند، همه جز اوریلوخوس که بیرون ماند، از ترس حیله."),
            StoryParagraph("And she gave them cheese and honey and meal and wine, and mixed a drug in the food.", "و به آنان پنیر و عسل و آرد و شراب داد و دارویی در خوراک آمیخت."),
            StoryParagraph("And when they had eaten, she struck them with her wand and drove them into a pigsty.", "و چون خوردند، با عصایش زدشان و به آغل خوک راندشان."),
            StoryParagraph("And they had the heads and voices and bristles of pigs, but their minds remained as before.", "و سر و صدا و موی خوک داشتند، اما ذهنشان همانند پیش بود."),
            StoryParagraph("And they wept as they were penned in, and Circe threw them acorns and cornel-berries to eat.", "و گریستند چون در آغل بسته شدند و کیرکه بلوط و میوه‌های دیگر برای خوردن به آنان انداخت."),
            StoryParagraph("And Eurylochus ran back to the ship and told us what had happened, and he could not speak for weeping.", "و اوریلوخوس به کشتی دوید و آنچه رخ داده بود به ما گفت و از گریستن نمی‌توانست سخن بگوید."),
            StoryParagraph("And I took my sword and my bow and told him to lead me back to the house of Circe.", "و شمشیر و کمانم را برداشتم و به او گفتم مرا به خانه کیرکه بازگرداند."),
            StoryParagraph("But he clung to my knees and begged me not to go, saying we would all be lost.", "اما به زانوهایم چنگ زد و التماس کرد نروم و گفت همه‌مان هلاک خواهیم شد."),
            StoryParagraph("But I went alone, and on the way I met Hermes, the god with the golden wand, in the form of a young man.", "اما تنها رفتم و در راه با هرمس دیدار کردم، خدای با عصای زرین، در هیئت جوانی."),
            StoryParagraph("And he took my hand and said: 'Where are you going, unhappy man? Your men are penned as pigs in Circe's house.'", "و دستم را گرفت و گفت: «کجا می‌روی، ای مرد بدبخت؟ یارانت همچون خوک در خانه کیرکه بسته‌اند.»"),
            StoryParagraph("'Take this herb, and go to Circe's house, and it will protect you from her drug. And when she strikes you with her wand, draw your sword and rush at her.'", "«این گیاه را بگیر و به خانه کیرکه برو و تو را از دارویش محافظت می‌کند. و چون با عصایش زدت، شمشیرت را بکش و بر او یورش بر.»"),
            StoryParagraph("'And she will be afraid, and will ask you to lie with her. But first make her swear a great oath not to harm you.'", "«و خواهد ترسید و از تو خواهد خواست با او بخوابی. اما نخست او را وادار کن سوگندی بزرگ بخورد که به تو آسیبی نرساند.»"),
            StoryParagraph("So he spoke, and gave me the herb, and I went on to the house of Circe, and my heart was troubled.", "این را گفت و گیاه را به من داد و به خانه کیرکه رفتم و دلم مضطرب بود."),
            StoryParagraph("And I called out, and Circe came and opened the doors and invited me in, and I followed her.", "و صدا زدم و کیرکه آمد و درها را گشود و دعوتم کرد و من پیرویش کردم."),
            StoryParagraph("And she gave me a cup, and I drank, and she struck me with her wand and said: 'Go now to the pigsty.'", "و جامی به من داد و نوشیدم و با عصایش زد و گفت: «اکنون به آغل خوک برو.»"),
            StoryParagraph("But I drew my sword and rushed at her, and she screamed and fell at my knees and begged me.", "اما شمشیرم را کشیدم و بر او یورش بردم و فریاد کشید و به زانوهایم افتاد و التماسم کرد."),
            StoryParagraph("'Who are you?' she said. 'What man are you? I have never met a man who could resist my drug. You must be Odysseus.'", "گفت: «تو کیستی؟ چه مردی هستی؟ هرگز مردی ندیده‌ام که دارویم را تاب آورد. باید اودیسئوس باشی.»"),
            StoryParagraph("And I made her swear the great oath, and then I went to her bed, and she became my friend.", "و وادارش کردم سوگند بزرگ بخورد و آنگاه به بسترش رفتم و دوستم شد."),
            StoryParagraph("And she released my men, and they came to me weeping, and they were men again, and we all rejoiced.", "و یارانم را رها کرد و گریان به سویم آمدند و باز مرد شدند و همه شادمان شدیم."),
            StoryParagraph("And Circe said: 'But first you must go to the house of Hades, to consult the spirit of Tiresias the prophet.'", "و کیرکه گفت: «اما نخست باید به خانه هادس بروی تا با روح تیرسیاس، پیشگو مشورت کنی.»"),
            StoryParagraph("And my heart was broken, and I wept, and I said: 'Who will guide us? No ship has ever sailed to the land of the dead.'", "و دلم خرد شد و گریستم و گفتم: «چه کسی راهنماییمان می‌کند؟ هیچ کشتی‌ای هرگز به سرزمین مردگان نرفته است.»"),
            StoryParagraph("And she told me what I must do, and what sacrifices to make, and I prepared myself for the journey.", "و به من گفت چه باید بکنم و چه قربانی‌هایی پیشکش کنم و خود را برای سفر آماده کردم."),
            StoryParagraph("And we stayed a year with Circe, feasting and resting, until at last my men asked me to remember our home.", "و یک سال با کیرکه ماندیم، ضیافت‌کنان و آسوده، تا سرانجام یارانم از من خواستند خانه‌مان را به یاد آورم."),
            StoryParagraph("And I went to Circe at night and lay at her knees, and asked her to send us home, for we longed for our own land.", "و شبانه پیش کیرکه رفتم و به زانوهایش افتادم و خواستم ما را به خانه بفرستد، زیرا مشتاق سرزمینمان بودیم."),
            StoryParagraph("And she said: 'I will not keep you against your will. But you must go to the house of Hades first, as I told you.'", "و گفت: «برخلاف میلت نگهت نمی‌دارم. اما نخست باید به خانه هادس بروی، چنان که گفتم.»"),
            StoryParagraph("And we set out, and a fair wind carried us to the edge of the world, where the Cimmerians live in mist and darkness.", "و به راه افتادیم و بادی موافق ما را به لبه جهان برد، جایی که کیمری‌ها در مه و تاریکی زندگی می‌کنند."),
            StoryParagraph("And there we dug a trench and poured libations to the dead, and I called to the spirit of Tiresias.", "و آنجا گودالی کندیم و به مردگان نوشیدنی‌ها پیشکش کردیم و روح تیرسیاس را فرا خواندم."),
            StoryParagraph("And the spirits came, and my mother among them, and I wept, for I did not know she was dead.", "و ارواح آمدند و مادرم میانشان و گریستم، زیرا نمی‌دانستم مرده است."),
            StoryParagraph("And Tiresias came, and told me of the many trials that awaited me, and warned me not to touch the cattle of Helios.", "و تیرسیاس آمد و از آزمون‌های بسیاری که در انتظارم بود گفت و هشدارم داد که به گاوهای هلیوس دست نزنم."),
            StoryParagraph("And I spoke with many heroes, and I saw my mother, and I tried to hold her, but she slipped through my arms like a shadow.", "و با قهرمانان بسیاری سخن گفتم و مادرم را دیدم و تلاش کردم در آغوشش بگیرم اما همچون سایه از میان دستانم لغزید."),
            StoryParagraph("And when we had done all, we returned to Circe, and she told us of the dangers that lay ahead.", "و چون همه را کردیم، به پیش کیرکه بازگشتیم و او از خطراتی که پیش رو بود گفت."),
            StoryParagraph("And she told us of the Sirens, and of Scylla and Charybdis, and of the cattle of Helios, and warned us to be careful.", "و از سیرن‌ها و از سیلا و خاریبدیس و از گاوهای هلیوس گفت و هشدار داد که مراقب باشیم."),
            StoryParagraph("And she sent a wind behind us, and we sailed from her island, and our hearts were heavy with sorrow.", "و بادی در پشت ما فرستاد و از جزیره‌اش دریانوردی کردیم و دل‌هایمان از اندوه سنگین بود."),
        )
    )

    // ─────────── فصل ۵: سیرن‌ها و گذرگاه‌های خطرناک ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Sirens and Dangerous Passages", titlePersian = "سیرن‌ها و گذرگاه‌های خطرناک",
        paragraphs = listOf(
            StoryParagraph("And I told my men about the Sirens, and I said: 'You must tie me to the mast, and if I beg you to let me go, tie me tighter.'", "و به یارانم از سیرن‌ها گفتم و گفتم: «باید مرا به دکل ببندید و اگر التماس کردم رهایم کنید، محکم‌تر ببندید.»"),
            StoryParagraph("And I filled the ears of all my men with wax, so they would not hear, and they tied me to the mast.", "و گوش همه یارانم را با موم پر کردم تا نشنوند و مرا به دکل بستند."),
            StoryParagraph("And I alone heard the Sirens' song, for I had not plugged my ears, but wanted to hear it once and live.", "و تنها من آواز سیرن‌ها را شنیدم، زیرا گوش‌هایم را نبسته بودم، بلکه می‌خواستم یک بار بشنوم و زنده بمانم."),
            StoryParagraph("And the Sirens sat in a meadow, and there were heaps of bones around them, of men who had listened and died.", "و سیرن‌ها در پاکشی نشسته بودند و توده‌های استخوان گردشان بود، از مردانی که گوش داده و مرده بودند."),
            StoryParagraph("And they sang: 'Come here, Odysseus, glory of the Achaeans, and listen to our song. No one has ever passed us without stopping.'", "و خواندند: «بیا اینجا، ای اودیسئوس، افتخار آخایی‌ها و به آواز ما گوش کن. هیچ‌کس هرگز بدون ایستادن از کنار ما نگذشته است.»"),
            StoryParagraph("'And whoever has heard us has gone on his way wiser and happier. For we know all that has happened at Troy, and all that will happen on earth.'", "«و هر که ما را شنیده، داناتر و شادمان‌تر راهش را رفته است. زیرا ما همه آنچه در تروا رخ داده را می‌دانیم و همه آنچه بر زمین رخ خواهد داد.»"),
            StoryParagraph("So they sang, and my heart longed to listen, and I made signs to my men to untie me.", "این را خواندند و دلم مشتاق شنیدن شد و به یارانم اشاره کردم بازم کنند."),
            StoryParagraph("But they remembered my orders and tied me tighter, and Perimedes and Eurylochus bound me with more rope.", "اما آنان دستوراتم را به یاد آوردند و محکم‌تر بستندم و پریمیدس و اوریلوخوس با طناب بیشتری بستندم."),
            StoryParagraph("And when we had passed the Sirens, they took the wax from their ears and untied me from the mast.", "و چون از سیرن‌ها گذشتیم، موم را از گوش‌هایشان برداشتند و مرا از دکل باز کردند."),
            StoryParagraph("But then I saw smoke and a great wave, and heard a terrible roar, and my men were afraid, and the oars fell from their hands.", "اما آنگاه دود و موجی بزرگ دیدم و غرشی هولناک شنیدم و یارانم ترسیدند و پاروها از دستانشان افتاد."),
            StoryParagraph("And I went among them and spoke to each man, and told them to be brave, for we had escaped worse dangers before.", "و میانشان رفتم و با هر مردی سخن گفتم و گفتم دلیر باشند، زیرا از خطرات بدتر پیش‌تر گریخته بودیم."),
            StoryParagraph("'Remember the Cyclops, and how we escaped from his cave,' I said. 'Be brave now, and row hard.'", "گفتم: «سیکلوپ را به یاد آورید و چگونه از غارش گریختیم. اکنون دلیر باشید و سخت پارو بزنید.»"),
            StoryParagraph("But I did not tell them about Scylla, for I knew they would stop rowing if they knew.", "اما از سیلا به آنان نگفتم، زیرا می‌دانستم اگر می‌دانستند از پارو زدن بازمی‌ایستادند."),
            StoryParagraph("And I forgot the warning of Circe, who had told me not to arm myself, for no man can fight Scylla.", "و هشدار کیرکه را فراموش کردم که گفته بود سلاح برندارم، زیرا هیچ مردی نمی‌تواند با سیلا بجنگد."),
            StoryParagraph("But I put on my armor and took two spears, and stood on the deck to watch for her.", "اما زره‌ام را پوشیدم و دو نیزه برداشتم و بر عرشه ایستادم تا مراقبش باشم."),
            StoryParagraph("And we came to the strait, and on one side was Scylla, the monster with twelve feet and six long necks and heads with three rows of teeth.", "و به تنگه رسیدیم و در یک سو سیلا بود، هیولا با دوازده پا و شش گردن بلند و سرهایی با سه ردیف دندان."),
            StoryParagraph("And on the other side was Charybdis, who three times a day sucked down the dark water, and three times spat it up again.", "و در سوی دیگر خاریبدیس بود که روزی سه بار آب تیره را می‌مکید و سه بار دیگر بازش می‌گرداند."),
            StoryParagraph("And we came to the narrowest part, and the men were rowing, and I looked at Charybdis and saw the water sucked away.", "و به تنگ‌ترین بخش رسیدیم و مردان پارو می‌زدند و به خاریبدیس نگاه کردم و دیدم آب مکیده می‌شود."),
            StoryParagraph("And while we stared at her, Scylla snatched six of my best men from the ship with her six heads.", "و همانطور که به او خیره شده بودیم، سیلا شش تن از بهترین یارانم را با شش سرش از کشتی ربود."),
            StoryParagraph("And I saw their hands and feet above me as they were carried up the rocks, and I heard their cries.", "و دست‌ها و پاهایشان را بالای سرم دیدم که به صخره‌ها برده می‌شدند و فریادشان را شنیدم."),
            StoryParagraph("And they called my name as they were eaten, and I could not help them, and it was the most terrible thing I saw on the sea.", "و نامم را صدا زدند همانطور که خورده می‌شدند و نمی‌توانستم کمکشان کنم و هولناک‌ترین چیزی بود که در دریا دیدم."),
            StoryParagraph("And we escaped from the strait, and came to the island of Helios, where his cattle grazed.", "و از تنگه گریختیم و به جزیره هلیوس رسیدیم، جایی که گاوهایش می‌چریدند."),
            StoryParagraph("And I remembered the warnings of Tiresias and Circe, and I told my men not to touch the cattle.", "و هشدارهای تیرسیاس و کیرکه را به یاد آوردم و به یارانم گفتم به گاوها دست نزنند."),
            StoryParagraph("'We must not touch the cattle of Helios,' I said, 'for he sees all things and hears all things.'", "گفتم: «نباید به گاوهای هلیوس دست بزنیم، زیرا او همه چیز را می‌بیند و همه چیز را می‌شنود.»"),
            StoryParagraph("But Eurylochus said: 'You are cruel, Odysseus. We are weary and hungry. Let us eat, and if the god is angry, let him destroy us, for it is better to die once than to waste away with hunger.'", "اما اوریلوخوس گفت: «بی‌رحمی، اودیسئوس. ما خسته و گرسنه‌ایم. بگذار بخوریم و اگر خدا خشمگین شد، بگذار نابودمان کند، زیرا بهتر است یک بار بمیریم تا از گرسنگی تحلیل رویم.»"),
            StoryParagraph("And I made them swear an oath not to touch the cattle, and they swore, and we stayed on the island.", "و قسمشان دادم به گاوها دست نزنند و قسم خوردند و در جزیره ماندیم."),
            StoryParagraph("But a south wind blew for a month, and no other wind came, and our food ran out.", "اما باد جنوبی یک ماه وزید و باد دیگری نیامد و خوراکمان تمام شد."),
            StoryParagraph("And my men hunted birds and fish, but there was not enough, and hunger gnawed at them.", "و یارانم پرنده و ماهی شکار کردند اما کافی نبود و گرسنگی آنان را می‌خورد."),
            StoryParagraph("And one day, when I was away praying to the gods, Eurylochus led the men to kill the finest cattle of Helios.", "و روزی، چون من دور بودم و به خدایان دعا می‌کردم، اوریلوخوس مردان را به کشتن بهترین گاوهای هلیوس برد."),
            StoryParagraph("And they sacrificed and ate, and the hides began to crawl, and the meat bellowed on the spits, though it was roasting.", "و قربانی کردند و خوردند و پوست‌ها شروع به خزیدن کردند و گوشت بر سیخ‌ها برشته، نعره می‌کشید."),
            StoryParagraph("And Helios was angry, and he went to Zeus and demanded justice for his cattle.", "و هلیوس خشمگین شد و به پیش زئوس رفت و برای گاوهایش عدالت خواست."),
            StoryParagraph("'Father Zeus,' he said, 'punish the men of Odysseus, for they have killed my cattle, which I loved.'", "گفت: «پدر زئوس، مردان اودیسئوس را مجازات کن، زیرا گاوهایم را که دوستشان داشتم کشتند.»"),
            StoryParagraph("And Zeus said: 'I will strike their ship with a thunderbolt and destroy them all in the midst of the sea.'", "و زئوس گفت: «کشتی‌شان را با آذرخش خواهم زد و همه‌شان را در میان دریا نابود خواهم کرد.»"),
            StoryParagraph("And when I came back and saw what they had done, I was filled with grief, and I knew that death was near.", "و چون بازگشتم و دیدم چه کرده بودند، پر از اندوه شدم و دانستم مرگ نزدیک است."),
            StoryParagraph("And we set sail, and the wind was fair, and we had gone but a little way from shore when the sky darkened.", "و بادبان کشیدیم و باد موافق بود و تنها کمی از ساحل دور شده بودیم که آسمان تاریک شد."),
            StoryParagraph("And a great black cloud came, and the sea rose, and a thunderbolt struck the ship and shattered it.", "و ابری سیاه و بزرگ آمد و دریا برخاست و آذرخشی کشتی را زد و خردش کرد."),
            StoryParagraph("And all my men were thrown into the sea and drowned, and I alone survived, clinging to the mast.", "و همه یارانم به دریا افتادند و غرق شدند و تنها من جان به سلامت بردم، چنگ‌زده به دکل."),
            StoryParagraph("And I bound the mast to the keel with a rope, and sat on it, and the wind carried me along.", "و دکل را با طناب به تیرک بستم و بر آن نشستم و باد مرا برد."),
            StoryParagraph("And I was carried back to Charybdis, and she sucked down the mast, and I clung to a fig tree above her.", "و به خاریبدیس بازگردانده شدم و او دکل را مکید و من به درخت انجیری بالای او چنگ زدم."),
            StoryParagraph("And I hung there until she spat out the mast again, and then I fell upon it and was carried away.", "و آنجا آویزان ماندم تا دکل را باز بیرون داد و آنگاه بر آن افتادم و برده شدم."),
            StoryParagraph("And for nine days I drifted, and on the tenth the gods brought me to the island of Calypso, where she welcomed me.", "و نُه روز رانده شدم و در دهم خدایان مرا به جزیره کالیپسو آوردند، جایی که او پذیرایم شد."),
            StoryParagraph("And so, in the cave of Calypso, I have lived for seven years, and she has loved me and cared for me.", "و این‌گونه، در غار کالیپسو، هفت سال زندگی کرده‌ام و او دوستم داشته و از من مراقبت کرده است."),
            StoryParagraph("And now I am on the shore of the Phaeacians, at the mouth of a river, with no ship, no men, and no hope.", "و اکنون در ساحل فایاسیایی‌ها هستم، در دهانه رودی، بی‌کشتی، بی‌مردان و بی‌امید."),
            StoryParagraph("But the gods have brought me here for a reason, and I wait for what will come, as I have waited for everything.", "اما خدایان مرا به اینجا برای دلیلی آورده‌اند و منتظر آنچه خواهد آمد هستم، چنان که برای همه چیز منتظر بوده‌ام."),
            StoryParagraph("For I am Odysseus, son of Laertes, known to men for my cunning, and known to the gods for my suffering.", "زیرا من اودیسئوس هستم، پسر لائرتس، شناخته‌شده در میان مردمان برای حیله‌ام و در میان خدایان برای رنجم."),
            StoryParagraph("And this is the story of my wanderings, which I have told to the Phaeacians, and which they have heard with wonder.", "و این داستان سرگردانی‌های من است که برای فایاسیایی‌ها گفته‌ام و آنان با شگفتی شنیده‌اند."),
            StoryParagraph("And now they have promised to take me home to Ithaca, in a swift ship, and I will at last see my wife and my son.", "و اکنون قول داده‌اند مرا در کشتی‌ای تندرو به ایتاکا ببرند و سرانجام همسرم و پسرم را خواهم دید."),
            StoryParagraph("But I know that more trials await me, and that the sea is not yet done with me, and that the gods will not let me rest.", "اما می‌دانم که آزمون‌های بیشتری در انتظارم است و دریا هنوز با من کارش تمام نشده و خدایان راحتم نخواهند گذاشت."),
        )
    )

    // ─────────── فصل ۶: بازگشت به ایتاکا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "Return to Ithaca", titlePersian = "بازگشت به ایتاکا",
        paragraphs = listOf(
            StoryParagraph("So the Phaeacians, famed for their ships, prepared a swift vessel to carry me home.", "پس فایاسیایی‌ها، نام‌آور به کشتی‌هایشان، کشتی‌ای تندرو آماده کردند تا مرا به خانه ببرد."),
            StoryParagraph("And they loaded it with gifts of bronze and gold and woven cloth, more than any man could hope for.", "و آن را با هدایایی از برنز و طلا و پارچه بافته بار کردند، بیش از آنچه هر مردی می‌توانست امیدوار باشد."),
            StoryParagraph("And at sunset we set sail, and the ship sped over the sea like a falcon, swift and sure.", "و هنگام غروب بادبان کشیدیم و کشتی همچون شاهینی بر دریا شتافت، تند و مطمئن."),
            StoryParagraph("And I lay on the deck and slept, for I was weary beyond words, and the sea rocked me like a child.", "و بر عرشه دراز کشیدم و خوابیدم، زیرا خسته‌تر از آن بودم که بگویم و دریا همچون کودکی تکانم می‌داد."),
            StoryParagraph("And when I woke, I did not know the land, for Athena had poured mist around me, to hide me from my enemies.", "و چون بیدار شدم، سرزمین را نمی‌شناختم، زیرا آتنا مهی گرد من پاشیده بود تا از دشمنانم پنهانم کند."),
            StoryParagraph("And I wept, for I thought the Phaeacians had abandoned me on a strange shore.", "و گریستم، زیرا گمان کردم فایاسیایی‌ها مرا در ساحلی بیگانه رها کرده‌اند."),
            StoryParagraph("And I fell on my knees and prayed to the gods, for I had no ship, no men, and no way to know where I was.", "و به زانو افتادم و به خدایان دعا کردم، زیرا نه کشتی داشتم، نه مرد، نه راهی برای دانستن اینکه کجا هستم."),
            StoryParagraph("But then Athena came to me, in the form of a young shepherd, and spoke to me with gentle words.", "اما آنگاه آتنا به سویم آمد، در هیئت چوپان جوانی و با سخنان نرم با من سخن گفت."),
            StoryParagraph("'Stranger, what land is this that you do not know?' she said, and she smiled, and her eyes shone.", "گفت: «ای بیگانه، این چه سرزمینی است که نمی‌شناسی؟» و لبخند زد و چشمانش درخشید."),
            StoryParagraph("'But know this: this is Ithaca, the land of Odysseus, and you are home, though you do not know it.'", "«اما این را بدان: این ایتاکا است، سرزمین اودیسئوس و تو به خانه‌ای، هرچند نمی‌دانی.»"),
            StoryParagraph("And I rejoiced, but I did not reveal myself, for I am cautious, and I told her a false tale of my origin.", "و شادمان شدم اما خود را آشکار نکردم، زیرا محتاطم و داستانی دروغ از اصل و نسبم به او گفتم."),
            StoryParagraph("And she laughed and said: 'You are indeed cunning, Odysseus, and I love you for it, for I am Athena, daughter of Zeus.'", "و خندید و گفت: «تو به‌راستی حیله‌گری، ای اودیسئوس و برای همین دوستت دارم، زیرا من آتنا هستم، دختر زئوس.»"),
            StoryParagraph("'And I have come to help you, for the gods have decreed that you shall punish the suitors and reclaim your house.'", "«و آمده‌ام تا کمکت کنم، زیرا خدایان مقدر کرده‌اند خواستگاران را مجازات کنی و خانه‌ات را بازپس گیری.»"),
            StoryParagraph("'But first you must go to the swineherd Eumaeus, who has been faithful to you, and he will take you in.'", "«اما نخست باید به نزد خوک‌چران اومایوس بروی، که به تو وفادار بوده و او تو را پناه خواهد داد.»"),
            StoryParagraph("And she touched me with her wand and changed my appearance, and I became an old beggar, in rags and wrinkled.", "و با عصایش لمسش کردم و ظاهرم را تغییر داد و پیر گدایی شدم، در ژنده و چین‌خورده."),
            StoryParagraph("And she told me to go to Eumaeus, and she went to Sparta, to bring Telemachus home from his journey.", "و به من گفت به نزد اومایوس بروم و خود به اسپارتا رفت تا تلماکوس را از سفرش بازگرداند."),
            StoryParagraph("And I went to the swineherd's hut, and he welcomed me, for he was a kind man, and he did not know me.", "و به کلبه خوک‌چران رفتم و او پذیرایم شد، زیرا مردی مهربان بود و مرا نمی‌شناخت."),
            StoryParagraph("And he fed me and gave me a cloak, and we sat by the fire and talked, and he spoke of his master, whom he loved.", "و خوراکم داد و شنلی بخشیدم و کنار آتش نشستیم و صحبت کردیم و او از اربابش گفت که دوستش داشت."),
            StoryParagraph("And he told me of the suitors, how they devoured the herds and drank the wine, and how Penelope put them off.", "و از خواستگاران گفت که چگونه گله‌ها را می‌خوردند و شراب را می‌نوشیدند و چگونه پنه‌لوپه سرشان را گرم می‌کرد."),
            StoryParagraph("And he told me that Penelope had promised to choose a husband when she finished weaving a shroud for Laertes.", "و گفت پنه‌لوپه قول داده بود چون بافتن کفنی برای لائرتس را تمام کند شوهری برگزیند."),
            StoryParagraph("'But she weaves by day and unravels by night,' he said, 'and so she has deceived them for three years.'", "گفت: «اما روزها می‌بافد و شب‌ها باز می‌کند و بدین‌سان سه سال است فریبشان داده.»"),
            StoryParagraph("And I listened, and my heart burned within me, but I said nothing, for I am patient above all men.", "و گوش دادم و دلم در درونم سوخت اما چیزی نگفتم، زیرا صبورتر از همه مردانم."),
            StoryParagraph("And Telemachus came home, for Athena had brought him safely, and he went first to the swineherd's hut.", "و تلماکوس به خانه بازگشت، زیرا آتنا به سلامت آورده بودش و نخست به کلبه خوک‌چران رفت."),
            StoryParagraph("And when he came in, I saw him, and my heart leapt, for he looked like a young god, and like my own youth.", "و چون درآمد، او را دیدم و دلم جست زد، زیرا همچون خدایی جوان بود و همچون جوانی خودم."),
            StoryParagraph("And Eumaeus rose and greeted him with tears of joy, and kissed his hands, as a father kisses a son returned.", "و اومایوس برخاست و با اشک شوق پذیرایش شد و دستانش را بوسید، همانطور که پدری پسر بازگشته را می‌بوسد."),
            StoryParagraph("And Telemachus asked who I was, and I told him a tale of Crete, of wandering and loss, and he listened.", "و تلماکوس پرسید کیستم و من داستانی از کرت گفتم، از سرگردانی و باختن و او گوش داد."),
            StoryParagraph("And when Eumaeus had gone to tell Penelope of her son's return, Athena appeared to me and changed me back.", "و چون اومایوس رفت تا به پنه‌لوپه از بازگشت پسرش بگوید، آتنا بر من ظاهر شد و به شکل اصلی‌ام بازگرداند."),
            StoryParagraph("And Telemachus saw me and was amazed, for I was no longer an old beggar, but a strong man in his prime.", "و تلماکوس مرا دید و شگفت‌زده شد، زیرا دیگر پیر گدایی نبودم، بلکه مردی نیرومند در عنفوان جوانی."),
            StoryParagraph("And I said: 'I am your father, Telemachus, for whom you have longed all these years.'", "و گفتم: «من پدر توام، تلماکوس، همان که این همه سال مشتاقش بوده‌ای.»"),
            StoryParagraph("And I kissed him, and my tears fell, for I had waited twenty years for this moment.", "و بوسیدمش و اشکم ریخت، زیرا بیست سال برای این لحظه منتظر مانده بودم."),
            StoryParagraph("But Telemachus did not believe me at first, and said: 'No, you are not my father, but some god has deceived me.'", "اما تلماکوس نخست باورم نکرد و گفت: «نه، تو پدر من نیستی، بلکه خدایی فریبم داده.»"),
            StoryParagraph("'For no mortal man could do what you have done, changing your shape before my eyes.'", "«زیرا هیچ مرد فانی نمی‌تواند آنچه تو کردی بکند، تغییر شکلت پیش چشمان من.»"),
            StoryParagraph("And I said: 'No god has done this, but Athena, who loves us both. And I am Odysseus, and I have come home at last.'", "و گفتم: «هیچ خدایی این را نکرده، بلکه آتنا، که هر دویمان را دوست دارد. و من اودیسئوسم و سرانجام به خانه آمده‌ام.»"),
            StoryParagraph("And then he embraced me, and wept, and we held each other, and the world seemed to stop.", "و آنگاه در آغوشم گرفت و گریست و همدیگر را گرفتیم و جهان به نظر ایستاد."),
            StoryParagraph("And we sat down and planned the destruction of the suitors, for there were more than a hundred of them.", "و نشستیم و نابودی خواستگاران را نقشه کشیدیم، زیرا بیش از صد تن بودند."),
            StoryParagraph("And Athena came to us and said: 'Do not fear, for I will fight beside you, and we will destroy them all.'", "و آتنا به نزدمان آمد و گفت: «نترسید، زیرا در کنارتان خواهم جنگید و همه‌شان را نابود خواهیم کرد.»"),
            StoryParagraph("And we planned, and I told Telemachus to go home and to hide all the weapons from the hall.", "و نقشه کشیدیم و به تلماکوس گفتم به خانه برود و همه سلاح‌ها را از تالار پنهان کند."),
            StoryParagraph("And I told him not to tell anyone who I was, not even Penelope, until the time was right.", "و گفتم به هیچ‌کس نگوید که من کیستم، نه حتی پنه‌لوپه، تا وقتی زمانش برسد."),
            StoryParagraph("And I told Eumaeus to take me to the town, disguised as a beggar, for I wanted to see my house and my wife.", "و به اومایوس گفتم مرا به شهر ببرد، در جامه گدایی، زیرا می‌خواستم خانه و همسرم را ببینم."),
            StoryParagraph("And so we went, and I stood at the door of my own house, and the suitors mocked me, and one threw a stool at me.", "و رفتیم و بر در خانه خودم ایستادم و خواستگاران مسخره‌ام کردند و یکی صندلی‌ای به سمتم انداخت."),
            StoryParagraph("And I bore it, for I am patient, and I entered and sat by the fire, and I waited for Penelope to come.", "و تحمل کردم، زیرا صبورم و به درون رفتم و کنار آتش نشستم و منتظر پنه‌لوپه ماندم."),
            StoryParagraph("And Penelope came down and spoke to me, for she had heard that I knew news of Odysseus.", "و پنه‌لوپه پایین آمد و با من سخن گفت، زیرا شنیده بود خبری از اودیسئوس دارم."),
            StoryParagraph("And I told her a tale of meeting Odysseus in a far land, and she wept, and I could not bear to see her tears.", "و داستانی از دیدار اودیسئوس در سرزمینی دور گفتم و او گریست و نتوانستم اشکش را ببینم."),
            StoryParagraph("And she told her maid Eurycleia to wash my feet, as was the custom for strangers.", "و به کنیزکش اوریکلیا گفت پاهایم را بشوید، چنان که رسم بیگانگان بود."),
            StoryParagraph("And Eurycleia saw the scar on my thigh, which a boar had given me long ago, and she knew me.", "و اوریکلیا زخم رانم را دید، همان که گرازی دیرزمانی پیش به من داده بود و مرا شناخت."),
            StoryParagraph("And she cried out, and I seized her throat and told her to be silent, for the time was not yet come.", "و فریاد کشید و گلویش را گرفتم و گفتم سکوت کند، زیرا زمانش نرسیده بود."),
            StoryParagraph("And Penelope did not know, for Athena had turned her eyes away, and she spoke to me of her sorrows.", "و پنه‌لوپه نمی‌دانست، زیرا آتنا چشمانش را برگردانده بود و از اندوه‌هایش به من گفت."),
            StoryParagraph("And she told me of the contest she would set the next day, for she had decided at last to choose a husband.", "و از مسابقه‌ای گفت که فردا برپا خواهد کرد، زیرا سرانجام تصمیم گرفته بود شوهری برگزیند."),
            StoryParagraph("'I will set the twelve axes of Odysseus in a row,' she said, 'and whoever can shoot an arrow through all twelve, him I will marry.'", "گفت: «دوازده تبر اودیسئوس را در ردیف می‌چینم و هر که بتواند تیری از میان همه دوازده بگذراند، با او ازدواج خواهم کرد.»"),
            StoryParagraph("And I rejoiced in my heart, for I knew that only Odysseus could do that, and I would be that man.", "و دلم شاد شد، زیرا می‌دانستم تنها اودیسئوس می‌تواند این کار را بکند و من همان مرد خواهم بود."),
            StoryParagraph("And I went to bed, and slept, and the next day dawned, and the contest was held, and the suitors tried and failed.", "و به بستر رفتم و خوابیدم و فردا سپیده آمد و مسابقه برگزار شد و خواستگاران تلاش کردند و ناکام ماندند."),
            StoryParagraph("And I asked to try, and they mocked me, but Penelope said: 'Let the stranger try, for it is his right.'", "و خواستم تلاش کنم و مسخره‌ام کردند اما پنه‌لوپه گفت: «بگذار بیگانه تلاش کند، زیرا حقش است.»"),
            StoryParagraph("And I took the bow, and strung it, and shot the arrow through all twelve axes, and the hall fell silent.", "و کمان را گرفتم و زهش کردم و تیر را از میان همه دوازده تبر گذراندم و تالار ساکت شد."),
            StoryParagraph("And Telemachus stood beside me with a sword, and Eumaeus barred the doors, and the slaughter began.", "و تلماکوس با شمشیری در کنارم ایستاد و اومایوس درها را بست و کشتار آغاز شد."),
            StoryParagraph("And I shot the suitors one by one, and they fell, and their blood ran on the floor of my house.", "و خواستگاران را یکی‌یکی زدم و افتادند و خونشان بر کف خانه‌ام ریخت."),
            StoryParagraph("And Athena came, and her aegis shone, and the suitors fled in terror, but there was no escape.", "و آتنا آمد و سپر مقدسش درخشید و خواستگاران از ترس گریختند اما راه فراری نبود."),
            StoryParagraph("And when all were dead, and the hall was cleansed, I revealed myself to Penelope, and she knew me at last.", "و چون همه مردند و تالار پاک شد، خود را به پنه‌لوپه آشکار کردم و سرانجام شناخت."),
            StoryParagraph("And she ran to me, and I held her, and we wept together, and the long years of waiting were over.", "و به سویم دوید و در آغوشش گرفتم و با هم گریستیم و سال‌های طولانی انتظار به پایان رسید."),
        )
    )

    // ─────────── فصل ۷: انتقام و آشتی ───────────
    private fun chapter7() = StoryChapter(
        number = 7, title = "Revenge and Reconciliation", titlePersian = "انتقام و آشتی",
        paragraphs = listOf(
            StoryParagraph("And Penelope came to me, and sat down opposite me, and looked at me, and did not speak.", "و پنه‌لوپه به سویم آمد و روبه‌رویم نشست و نگاهم کرد و چیزی نگفت."),
            StoryParagraph("And I said to Telemachus: 'Let your mother ask me questions, and I will answer, for I have nothing to hide.'", "و به تلماکوس گفتم: «بگذار مادرت از من بپرسد و من پاسخ دهم، زیرا چیزی برای پنهان کردن ندارم.»"),
            StoryParagraph("And Penelope said: 'Strange man, tell me who you are, and where you come from, for your words are like those of Odysseus.'", "و پنه‌لوپه گفت: «ای مرد عجیب، به من بگو کیستی و از کجایی، زیرا سخنانت همچون سخنان اودیسئوس است.»"),
            StoryParagraph("And I told her of the scar on my thigh, and of the olive tree that I had built our bed around, and she wept.", "و از زخم رانم گفتم و از درخت زیتونی که بسترمان را گرد آن ساخته بودم و گریست."),
            StoryParagraph("For she had asked Eurycleia to move the bed, and I had said: 'No one can move that bed, for I built it around the trunk of an olive tree.'", "زیرا او از اوریکلیا خواسته بود بستر را جابه‌جا کند و من گفته بودم: «هیچ‌کس نمی‌تواند آن بستر را تکان دهد، زیرا آن را گرد تنه درخت زیتونی ساخته‌ام.»"),
            StoryParagraph("And when she heard this, she knew that I was truly Odysseus, and she ran to me and threw her arms around me.", "و چون این را شنید، دانست که من به‌راستی اودیسئوسم و به سویم دوید و مرا در آغوش گرفت."),
            StoryParagraph("And I held her, and we wept together, and the twenty years of separation were washed away in our tears.", "و در آغوشش گرفتم و با هم گریستیم و بیست سال جدایی در اشک‌هایمان شسته شد."),
            StoryParagraph("And the dawn would have found us weeping, but Athena held back the dawn, and lengthened the night, that we might have time.", "و سپیده ما را گریان می‌یافت، اما آتنا سپیده را بازداشت و شب را دراز کرد تا وقت داشته باشیم."),
            StoryParagraph("And we talked all night, of all that had happened, of all that we had suffered, of all that we had lost.", "و تمام شب صحبت کردیم، از همه آنچه رخ داده بود، از همه آنچه کشیده بودیم، از همه آنچه از دست داده بودیم."),
            StoryParagraph("And she told me of the suitors, and of how she had deceived them for three years with the shroud.", "و از خواستگاران گفت و از اینکه چگونه سه سال با کفن فریبشان داده بود."),
            StoryParagraph("And she told me of Telemachus, and of how he had grown, and of how he had gone to seek news of me.", "و از تلماکوس گفت و از اینکه چگونه بزرگ شده بود و چگونه رفته بود خبری از من بجوید."),
            StoryParagraph("And I told her of Troy, and of the wooden horse, and of the sack of the city, and of my wanderings.", "و از تروا گفتم و از اسب چوبی و از غارت شهر و از سرگردانی‌هایم."),
            StoryParagraph("And I told her of Calypso, and of Circe, and of the Cyclops, and of all the dangers I had faced.", "و از کالیپسو گفتم و از کیرکه و از سیکلوپ و از همه خطراتی که با آن‌ها روبرو شده بودم."),
            StoryParagraph("And when morning came, I said: 'Now I must go to my father Laertes, who lives in the country, and who has suffered long.'", "و چون بامداد آمد گفتم: «اکنون باید به نزد پدرم لائرتس بروم، که در حومه زندگی می‌کند و دیرزمانی رنج کشیده.»"),
            StoryParagraph("But before I went, I told the servants to make music, so that the neighbors would not know what had happened.", "اما پیش از رفتن به خدمتکاران گفتم موسیقی بنوازند تا همسایگان نفهمند چه رخ داده."),
            StoryParagraph("For if they knew that the suitors were dead, the city would be in an uproar, and their families would seek revenge.", "زیرا اگر می‌دانستند خواستگاران مرده‌اند، شهر در آشوب می‌شد و خانواده‌هایشان انتقام می‌خواستند."),
            StoryParagraph("And so the music played, and the people thought a wedding was being held, and they did not suspect.", "و این‌گونه موسیقی نواخته شد و مردمان گمان کردند عروسی برگزار می‌شود و گمان بد نبردند."),
            StoryParagraph("And I went to the country, to the farm of Laertes, and I found him in the garden, digging around a plant.", "و به حومه رفتم، به مزرعه لائرتس و او را در باغ یافتم، گرد گیاهی را می‌کند."),
            StoryParagraph("And he was old and worn, and he wore patched clothes, and he looked like a slave, not a king.", "و پیر و فرسوده بود و جامه پیوندی پوشیده بود و همچون برده‌ای به نظر می‌رسید، نه پادشاهی."),
            StoryParagraph("And I stood at a distance and wept, for it was hard to see my father so broken.", "و از دور ایستادم و گریستم، زیرا سخت بود دیدن پدرم را این‌گونه شکسته."),
            StoryParagraph("And I spoke to him, and told him a tale of a stranger who had met Odysseus, and he wept and said: 'I have no son.'", "و با او سخن گفتم و داستانی از بیگانه‌ای گفتم که اودیسئوس را دیده بود و او گریست و گفت: «پسری ندارم.»"),
            StoryParagraph("And then I could bear it no longer, and I revealed myself, and I showed him the scar, and I embraced him.", "و آنگاه دیگر نتوانستم تحمل کنم و خود را آشکار کردم و زخم را نشانش دادم و در آغوشش گرفتم."),
            StoryParagraph("And he cried out: 'Odysseus, my son, my son!' and he held me, and his tears fell on my shoulders.", "و فریاد کشید: «اودیسئوس، پسرم، پسرم!» و مرا گرفت و اشکش بر شانه‌هایم ریخت."),
            StoryParagraph("And I told him of the suitors, and of their death, and of how I had reclaimed my house.", "و از خواستگاران گفتم و از مرگشان و از اینکه چگونه خانه‌ام را بازپس گرفته بودم."),
            StoryParagraph("And we went back to the house, and Dolius and his sons came, and we all ate together, and rejoiced.", "و به خانه بازگشتیم و دولیوس و پسرانش آمدند و همه با هم خوردیم و شادمان شدیم."),
            StoryParagraph("But meanwhile, the families of the suitors had gathered, and they were angry, and they wanted revenge.", "اما در همین حال، خانواده‌های خواستگاران گرد آمده بودند و خشمگین بودند و انتقام می‌خواستند."),
            StoryParagraph("And they came to the house of Odysseus, armed, and they were many, and they shouted for my death.", "و به خانه اودیسئوس آمدند، مسلح و بسیار بودند و مرگ من را فریاد می‌زدند."),
            StoryParagraph("And I put on my armor, and Telemachus put on his, and Laertes put on his, and we stood together.", "و من زره‌ام را پوشیدم و تلماکوس زره‌اش را و لائرتس زره‌اش را و با هم ایستادیم."),
            StoryParagraph("And Athena came to us, disguised as Mentor, and she stood beside us, and her aegis shone.", "و آتنا به نزدمان آمد، در جامه منتور و در کنارمان ایستاد و سپر مقدسش درخشید."),
            StoryParagraph("And Laertes threw his spear first, and it struck Antinous' father, and he fell dead.", "و لائرتس نخست نیزه‌اش را انداخت و پدر آنتینووس را زد و مرده افتاد."),
            StoryParagraph("And we charged, and the families fled, and Athena cried out with a great voice: 'Stop, men of Ithaca, and shed no more blood!'", "و یورش بردیم و خانواده‌ها گریختند و آتنا با آوازی بزرگ فریاد زد: «ای مردان ایتاکا، بازایستید و دیگر خون نریزید!»"),
            StoryParagraph("And they stopped, and they fled, and they did not look back, and peace came to Ithaca.", "و بازایستادند و گریختند و به عقب نگاه نکردند و صلح به ایتاکا آمد."),
            StoryParagraph("And Athena made a covenant between the families and Odysseus, and both sides swore to keep it.", "و آتنا پیمانی میان خانواده‌ها و اودیسئوس بست و هر دو سو قسم خوردند نگهش دارند."),
            StoryParagraph("And so Odysseus, the man of many ways, came home at last, after twenty years of war and wandering.", "و این‌گونه اودیسئوس، مرد بسیار‌راه‌رفته، سرانجام پس از بیست سال جنگ و سرگردانی به خانه بازگشت."),
            StoryParagraph("And he ruled in Ithaca, and he lived with Penelope, and he saw his son grow into a man.", "و در ایتاکا فرمان راند و با پنه‌لوپه زندگی کرد و پسرش را دید که مردی شد."),
            StoryParagraph("And the gods gave him peace at last, and he grew old among his people, and he was honored by all.", "و خدایان سرانجام به او صلح دادند و در میان مردمانش پیر شد و همه حرمتش نهادند."),
            StoryParagraph("But the sea never left him, and in his dreams he still heard the waves, and saw the shores of distant lands.", "اما دریا هرگز رهایش نکرد و در رؤیاهایش هنوز امواج را می‌شنید و ساحل سرزمین‌های دور را می‌دید."),
            StoryParagraph("For a man who has wandered long upon the sea carries the sea within him, and he is never wholly at rest.", "زیرا مردی که دیرزمانی بر دریا سرگردان بوده، دریا را در درون خود دارد و هرگز به‌طور کامل آرام نمی‌گیرد."),
            StoryParagraph("And he would sit on the shore at evening, looking out at the wine-dark sea, and remember.", "و شب‌ها در ساحل می‌نشست و به دریای شراب‌گون خیره می‌شد و به یاد می‌آورد."),
            StoryParagraph("He remembered the friends he had lost, and the cities he had seen, and the monsters he had fought.", "دوستان از دست‌رفته‌اش را به یاد می‌آورد و شهرهایی که دیده بود و هیولاهایی که با آن‌ها جنگیده بود."),
            StoryParagraph("And he remembered Calypso, who had loved him, and Circe, who had helped him, and the many who had died.", "و کالیپسو را به یاد می‌آورد که دوستش داشت و کیرکه را که کمکش کرد و بسیاری را که مرده بودند."),
            StoryParagraph("And he knew that his story would be told for generations, and that his name would never be forgotten.", "و می‌دانست که داستانش نسل‌ها گفته خواهد شد و نامش هرگز فراموش نخواهد شد."),
            StoryParagraph("For he was Odysseus, the man of many ways, who suffered much and endured much, and who came home at last.", "زیرا او اودیسئوس بود، مرد بسیار‌راه‌رفته، که بسیار رنج کشید و بسیار تاب آورد و سرانجام به خانه بازگشت."),
            StoryParagraph("And so the tale ends, as all tales must, with a man at peace, in his own house, with his own people.", "و این‌گونه داستان پایان می‌یابد، چنان که همه داستان‌ها باید، با مردی در آرامش، در خانه خودش، با مردمان خودش."),
            StoryParagraph("But the sea still calls, and the road still stretches, and there is always another journey waiting.", "اما دریا هنوز می‌خواند و جاده هنوز کشیده است و همیشه سفر دیگری در انتظار است."),
            StoryParagraph("And that is the way of men who love the sea, and of men who love adventure, and of men who cannot rest.", "و این راه مردانی است که دریا را دوست دارند و مردانی که ماجراجویی را دوست دارند و مردانی که نمی‌توانند بیاسایند."),
            StoryParagraph("And Odysseus was such a man, and his story is the story of all such men, in every age.", "و اودیسئوس چنین مردی بود و داستانش داستان همه چنین مردانی است، در هر عصر."),
            StoryParagraph("Sing to me, Muse, of the man of many ways, who wandered long, and who came home at last.", "ای موز، برایم بخوان از مرد بسیار‌راه‌رفته، که دیرزمانی سرگردان بود و سرانجام به خانه بازگشت."),
            StoryParagraph("The end.", "پایان."),
        )
    )
}